// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Amerikan, Latin Amerika ve Alman edebiyatı (orta).
const ozLiterature11Orta = <(String, String, List<String>, String)>[
  ('Anne Bradstreet\'i Amerikan edebiyat tarihinde özel kılan nedir?', 'Kuzey Amerika\'da şiir kitabı yayımlanan ilk kadın şair olması', ['Kuzey Amerika\'da roman yayımlayan ilk kadın yazar olması ve bunu takma adla yapması', 'Kızılderili dillerinde şiir yazan ilk beyaz kadın olması', 'Püriten kilisesinin ilk kadın vaizi olması'], 'Bradstreet\'in şiirleri 1650\'de Londra\'da yayımlandı. Püriten ev yaşamını ve dinî duyguları işleyen dizeleriyle tanınır.'),
  ('Benjamin Franklin\'in \'Otobiyografi\'sinde kendini geliştirmek için tuttuğu planın temelini hangisi oluşturur?', 'Her hafta bir erdeme odaklanarak on üç erdemden oluşan bir çizelgeyi izlemek', ['Her gün bir saat Kutsal Kitap okumak', 'Yılda bir kez kamuoyu önünde günah çıkarmak', 'Her ay yeni bir dil öğrenmeyi hedeflemek'], 'Franklin, ölçülülük ve çalışkanlık gibi on üç erdemi hafta hafta uygulamaya çalıştığını anlatır. Bu, Aydınlanma çağının pratik akılcılığının örneğidir.'),
  ('Phillis Wheatley\'nin 1773\'te yayımlanan şiir kitabı neden tarihsel önem taşır?', 'Afrikalı Amerikalı bir yazarın ilk şiir kitabı olması', ['Kızılderili halk şiirlerini derleyen ilk kitap olması', 'Bağımsızlık Savaşı sırasında cephede yazılmış ilk şiir derlemesi olması', 'Amerika\'da basılan ilk İngilizce şiir kitabı olması'], 'Köle olarak Boston\'a getirilen Wheatley, kitabı yayımlanan ilk Afrikalı Amerikalı şair oldu. Kitap Londra\'da basıldı.'),
  ('Frederick Douglass\'ın 1845 tarihli \'Anlatı\'sı, köleliğe karşı mücadelede hangi işlevi gördü?', 'Bir kölenin kendi sesiyle tanıklık ederek köleliğin vahşetini kamuoyuna duyurması', ['Köle sahiplerine yasal tavsiyeler vermesi', 'Güney eyaletlerinin ekonomisini savunması', 'Afrika\'ya geri dönüş projesini önermesi'], 'Douglass, kaçak bir köle olarak yazdığı anlatıyla kölelik karşıtı hareketin en güçlü tanıklıklarından birini sundu.'),
  ('Cooper\'ın romanlarında Kızılderili kahramanlar ile sınır boyu avcısı arasındaki dostluk, Amerikan edebiyatında hangi temanın başlangıcı sayılır?', 'Uygarlık ile vahşi doğa arasındaki gerilim', ['Sanayileşme ve kent yaşamı', 'Göçmenlerin kimlik arayışı', 'İç savaşın ahlaki sorunları'], 'Cooper\'ın sınır romanları, yerleşik uygarlık ile vahşi doğa arasındaki çatışmayı işleyerek Amerikan yazınının sonraki \'Batı\' anlatılarına zemin hazırladı.'),
  ('Poe\'nun \'Altın Böcek\' öyküsündeki hazine haritasının şifresi hangi yöntemle çözülür?', 'Harflerin sıklık analiziyle', ['Aynadaki yansımasını okuyarak', 'Kimyasal mürekkeple', 'Kuş seslerini taklit ederek'], 'Legrand, şifreli metindeki en sık geçen simgeyi \'e\' harfi sayarak çözümlemeye başlar. Öykü, şifre çözmeyi edebiyata taşıyan ilk örneklerdendir.'),
  ('Melville\'in \'Billy Budd\' adlı uzun öyküsünde genç denizcinin ölümüne yol açan olayı hangisi tetikler?', 'Kıdemli subay Claggart\'ın yalan ithamda bulunması', ['Gemideki bir isyan', 'Yakalanan bir korsan', 'Kaptanın deliliği'], 'Billy Budd, kendisini asılsız biçimde isyancı olmakla suçlayan Claggart\'ı bir yumrukla öldürür ve yasa gereği idam edilir.'),
  ('Bir öğrenci, Amerikan Romantizminin \'iyimser\' kanadı ile \'karanlık\' kanadını karşılaştıracaktır. Hangi eşleştirme doğrudur?', 'Emerson iyimser, Poe karanlık kanada örnektir', ['Whitman karanlık, Hawthorne iyimser kanada örnektir', 'Thoreau karanlık, Melville iyimser kanada örnektir', 'Dickinson iyimser, Emerson karanlık kanada örnektir'], 'Emerson ve Thoreau insana ve doğaya güvenirken Poe, Hawthorne ve Melville günahı, suçu ve kötülüğü ön plana çıkarır.'),
  ('Emerson\'ın 1837\'de Harvard\'da verdiği \'Amerikalı Âlim\' konuşması, Amerikan düşün tarihinde neden önemli sayılır?', 'Avrupa\'dan bağımsız bir Amerikan düşünce ve edebiyatı çağrısı yaptığı için', ['Kölelik karşıtı mücadelenin ilk resmî bildirisi sayıldığı ve Kongre\'de okunduğu için', 'Amerikan Anayasası\'nı eleştirdiği için', 'Püriten inançları yeniden savunduğu için'], 'Oliver Wendell Holmes bu konuşmayı \'Amerikan entelektüel bağımsızlık bildirgesi\' diye nitelemiştir.'),
  ('Thoreau\'nun \'Sivil İtaatsizlik\' denemesine ilham veren olay, yazarın hangi davranışıdır?', 'Köleliği ve Meksika Savaşı\'nı destekleyen hükümete vergi vermeyi reddetmesi', ['Orduya gönüllü yazılmayı reddetmesi', 'Oy kullanmaması', 'Ülkeyi terk edip Kanada\'ya gitmesi'], 'Thoreau vergi vermediği için bir gece hapse atıldı. Denemesi, sonradan Gandhi ve Martin Luther King\'in düşüncelerini etkiledi.'),
  ('Whitman\'ın şiirlerinde sıkça kullandığı \'Kendimin Şarkısı\' adlı uzun şiirin bakış açısı en çok neyi vurgular?', 'Bireyin kendini evrenle ve demokratik kitleyle özdeşleştirmesini', ['Yalnız kalmanın hüznünü', 'Geçmişe duyulan özlemi', 'Dinî günahtan arınma çabasını'], 'Şiirde \'ben\' hem tekil birey hem de bütün insanlığı temsil eder; bu, Whitman\'ın demokratik ve kapsayıcı şiir anlayışını gösterir.'),
  ('Whitman\'ın \'Çimen Yaprakları\' kitabı ilk basıldığında yazarın adı nasıl yer alıyordu?', 'Kapakta ad yoktu; yalnızca portresi yer alıyordu', ['Takma adla basılmıştı ve yazarın gerçek adı sonradan öğrenilmişti', 'Ön sözü Emerson adına yazılmıştı', 'Kitabın sahibi olarak yayıncı gösterilmişti'], '1855 baskısında Whitman\'ın adı kapakta yoktu; adı yalnızca uzun şiirin içinde geçiyordu. Emerson\'un övgü mektubu sonradan baskıya eklendi.'),
  ('Whitman ile Dickinson\'ın şiir biçimleri karşılaştırıldığında hangisi doğrudur?', 'Whitman uzun, serbest dizeler; Dickinson kısa, yoğun dörtlükler kullanır', ['Her ikisi de katı kafiye düzenine uyan, yalnızca soneler yazan şairlerdir', 'Whitman kısa, Dickinson uzun dizeler kullanır', 'İkisi de yalnızca düzyazı şiir yazmıştır'], 'Whitman\'ın geniş soluklu serbest ölçüsü ile Dickinson\'ın kısa, kesik ve tireli dizeleri, Amerikan şiirinin iki farklı yenilikçi kolunu oluşturur.'),
  ('\'Yaldızlı Çağ\' deyimi, Twain ve Charles Dudley Warner\'ın aynı adlı romanından hareketle 19. yüzyıl sonu Amerika\'sını nasıl niteler?', 'Parlak bir yüzeyin altında yozlaşma ve açgözlülüğün bulunduğu dönem', ['Altın madenciliğinin yaygınlaştığı dönem', 'Sanatların altın çağı', 'Savaşın bittiği barış yılları'], 'Terim, zenginliğin ve gösterişin gölgesinde yolsuzluğu ve sahteciliği eleştirir.'),
  ('Kate Chopin\'in \'Uyanış\' romanı yayımlandığında sert tepki görmesinin başlıca nedeni nedir?', 'Evli bir kadının bireysel özgürlük ve cinsel kimlik arayışını açıkça işlemesi', ['Köleliği desteklemesi', 'Askerî sırları ifşa etmesi', 'Dine saldıran siyasi bir manifesto olması'], 'Edna Pontellier\'in toplumsal rolleri reddedişi 1899\'da skandal sayıldı; kitap yıllar sonra feminist edebiyatın klasiği olarak yeniden değerlendirildi.'),
  ('Ambrose Bierce\'in \'Owl Creek Köprüsü\'nde Bir Olay\' öyküsünde okuru şaşırtan son hangisidir?', 'Kurtulduğunu sanan idam mahkûmunun aslında idam anında düşlediği ortaya çıkar', ['Kahramanın uyanıp tüm olanları rüya gördüğünü fark etmesi ve eşinin yanında olması', 'Köprünün çökmesi ve herkesin ölmesi', 'Kahramanın cezasının hafifletilmesi'], 'Kahraman ipten düştüğü anda uzun bir kaçış yaşadığını sanır; son cümle onun boynunun kırıldığını gösterir.'),
  ('Henry James\'in romanlarının ortak teması nedir?', 'Masum Amerikalılarla Avrupa\'nın deneyimli ve karmaşık toplumunun karşılaşması', ['Sınır boylarında hayatta kalma mücadelesi', 'İşçi sınıfının grevleri', 'Köle isyanları'], '\'Bir Kadının Portresi\' gibi eserlerde James, Amerikalı karakterlerin Avrupa\'da yaşadığı ahlaki ve duygusal sınavları ince bir psikolojik çözümlemeyle anlatır.'),
  ('\'Muhteşem Gatsby\'de olayları anlatan Nick Carraway\'in Gatsby\'ye karşı konumu nasıldır?', 'Hem olayların içinde yer alan hem de onlara mesafeli bakan tanık-anlatıcıdır', ['Her şeyi bilen, olaylara hiç karışmayan ve tüm karakterlerin zihnine giren üçüncü kişi anlatıcıdır', 'Gatsby\'nin kendisidir', 'Daisy\'nin eşi Tom\'dur'], 'Nick, birinci kişi anlatıcı olarak Gatsby\'yi hayranlık ve eleştiriyle gözlemler; bu mesafe romana güvenilirlik ve yorum katmanı katar.'),
  ('Gatsby romanındaki Doktor T. J. Eckleburg\'un reklam panosundaki gözleri neyin simgesi olarak yorumlanır?', 'Tanrı\'nın ya da ahlaki yargının terk edilmiş hâli', ['Zenginlik ve lüks', 'İş dünyasının başarısı', 'Savaşın anıları'], 'Kül Vadisi\'nin üzerinde duran soluk gözler, ahlaki çürümeyi izleyen sessiz bir yargıç gibi okunur.'),
  ('Hemingway\'in \'Silahlara Veda\' romanında Frederic Henry\'nin hangi cephede görev yaptığı anlatılır?', 'Birinci Dünya Savaşı\'nda İtalyan cephesinde ambulans sürücüsü olarak', ['İkinci Dünya Savaşı\'nda Normandiya\'da paraşütçü olarak', 'İspanya İç Savaşı\'nda gazeteci olarak', 'Kore Savaşı\'nda pilot olarak'], 'Frederic Henry İtalyan cephesinde ambulans subayıdır; hemşire Catherine Barkley ile aşkı savaşın anlamsızlığıyla iç içedir.'),
  ('\'Çanlar Kimin İçin Çalıyor\' romanında dinamitçi Robert Jordan hangi olayın içinde yer alır?', 'İspanya İç Savaşı\'nda bir köprüyü havaya uçurma görevinde', ['Normandiya çıkarmasında öncü birliğin paraşütçüsü olarak görevde', 'Meksika Devrimi\'nde', 'Vietnam Savaşı\'nda'], 'Hemingway, gerçek bir İspanya İç Savaşı deneyimine dayanarak, Cumhuriyetçi gerillalarla köprü patlatma görevini anlatır.'),
  ('Hemingway\'in ölümünden sonra yayımlanan \'Paris Bir Şölendir\' adlı anı kitabı hangi dönemi anlatır?', '1920\'lerde Paris\'te genç bir yazar olarak geçirdiği yılları', ['Savaş muhabirliği yaptığı İspanya İç Savaşı günlerini ve cephe anılarını', 'Küba\'daki son yıllarını', 'Afrika safarilerini'], 'Kitap, Hemingway\'in Gertrude Stein, Fitzgerald ve Pound gibi isimlerle tanıştığı Paris yıllarının anısıdır.'),
  ('Faulkner\'ın \'Döşeğimde Ölürken\' romanında Bundren ailesi hangi görevi yerine getirmeye çalışır?', 'Ölen anneyi vasiyeti gereği Jefferson\'daki mezarlığa götürmeyi', ['Çiftliği satıp şehre taşınmayı', 'Kaybolan bir çocuğu bulmayı', 'Bir cinayet davasında tanıklık etmeyi'], 'Addie Bundren\'in cenazesini taşıyan ailenin zorlu yolculuğu, farklı iç seslerle aktarılır.'),
  ('Faulkner\'ın \'Absalom, Absalom!\' romanında Thomas Sutpen\'in hırsı neyi hedefler?', 'Büyük bir plantasyon kurup bir soy yaratmayı', ['Kuzey ordusunda general olup soyunu ün kazandırmayı', 'Kuzey ordusuna katılmayı', 'Bir kilise yaptırmayı'], 'Sutpen\'in \'tasarısı\', kölelik toplumunun mirasını ve ırk meselesini sorgulayan trajik bir yıkıma dönüşür.'),
  ('Faulkner\'ın 1949 Nobel konuşmasında insanla ilgili vurguladığı düşünce hangisidir?', 'İnsanın yalnız dayanmakla kalmayıp galip geleceğine inandığı', ['İnsanlığın yok olmak üzere olduğu, atom bombasından sonra edebiyatın bittiği düşüncesini', 'Savaşın kaçınılmaz olduğu', 'Edebiyatın artık işe yaramadığı'], 'Faulkner \'insanın yalnızca dayanmayacağına, galip geleceğine inanıyorum\' diyerek yazarın görevinin umudu canlı tutmak olduğunu söyledi.'),
  ('Faulkner\'ın \'Ağustos Işığı\' romanında Joe Christmas\'ın trajedisi hangi toplumsal soruna bağlanır?', 'Kendi ırksal kimliğinin belirsizliği ve ırkçılık', ['Savaş travması', 'Din değiştirme', 'İşsizlik'], 'Joe Christmas\'ın siyah mı beyaz mı olduğu belirsizdir; Güney\'in katı ırk ayrımı onu yıkıma götürür.'),
  ('\'Güney Gotiği\' türüne örnek olarak gösterilen Flannery O\'Connor\'ın öykülerinde sıkça ele alınan konu hangisidir?', 'Kırsal Güney\'de inanç, çarpıklık ve beklenmedik şiddet', ['Uzay yolculuğu, bilimkurgu serüvenleri ve uzak gezegenlerdeki yaşam', 'Büyük şehir hayatı', 'Savaş sonrası Avrupa'], 'O\'Connor\'ın katı Katolik bakışı, \'Bir İyi Adam Zor Bulunur\' gibi öykülerinde şiddetle sonuçlanan ahlaki epifanilere dönüşür.'),
  ('Zora Neale Hurston\'ın \'Gözleri Tanrı\'ya Bakıyordu\' romanında Janie Crawford\'un yolculuğu en çok neyi öne çıkarır?', 'Siyah bir kadının kendi sesini ve özgürlüğünü bulması', ['Büyük bir servet kazanıp New York\'ta lüks içinde yaşaması ve ünlenmesi', 'Savaşta kahramanlığı', 'Bilimsel bir keşif yapması'], 'Janie, üç evlilik sonunda kendine ait bir kimlik kazanır; roman Harlem Rönesansı\'nın önemli eseridir.'),
  ('Arthur Miller\'ın \'Hepsi Benim Oğullarım\' oyunundaki Joe Keller\'ın ailesini yıkıma götüren suçu nedir?', 'Savaş sırasında kusurlu uçak parçalarının satılmasına göz yummuş olması', ['Kardeşinin mirasını çalması', 'Bir cinayetin tanığını susturması', 'Vergi kaçırması'], 'Keller\'ın kusurlu silindir kafalarını göndermesi pilotların ölümüne yol açar; oğlu gerçeği öğrenince babasının suçuyla yüzleşir.'),
  ('Lorraine Hansberry\'nin \'Güneşte Bir Kuru Üzüm\' oyununun adı hangi şairin dizesinden alınmıştır?', 'Langston Hughes', ['Edna St. Vincent Millay', 'Robert Frost', 'Carl Sandburg'], 'Hughes\'un \'Ertelenmiş bir düş neye döner? Güneşte bir kuru üzüm gibi mi kurur?\' dizesi oyunun epigrafıdır. Oyun, siyah bir ailenin konut düşünü anlatır.'),
  ('Hansberry\'nin oyununda Younger ailesinin sigorta parasıyla yapmak istediği şey ve karşılaştıkları engel nedir?', 'Beyazlar mahallesinde ev almak; buradaki ırkçı direnç', ['Dükkân açmak; vergi borcu', 'Okul yaptırmak; iç savaş', 'Tiyatro kurmak; sansür'], 'Aile, beyazların oturduğu mahallede ev satın alır; mahalle derneği evi geri satın almak ister. Oyun ırk ayrımcılığını işler.'),
  ('Tony Kushner\'in \'Amerika\'da Melekler\' oyunu hangi dönemin toplumsal gerilimini işler?', '1980\'lerin AIDS krizi ve Reagan dönemi siyasetini', ['1930\'ların Buhranını', '1960\'ların uzay yarışını', '1990\'ların internet çağını'], 'Oyun, eşcinsellik, hastalık, din ve siyaset temalarını fantastik öğelerle birleştirir.'),
  ('Eliot\'un \'Çorak Ülke\' şiirinin el yazmasını düzelten ve şairin eserine \'daha iyi demirci\' diye ithaf ettiği kişi kimdir?', 'Ezra Pound', ['Wallace Stevens', 'William Carlos Williams', 'Robert Frost'], 'Pound, şiirin uzun taslağını ciddi biçimde kısaltıp yoğunlaştırdı; Eliot ithafta \'il miglior fabbro\' ifadesini kullandı.'),
  ('Edgar Lee Masters\'ın \'Spoon River Antolojisi\'nin kurgusal yapısı nasıldır?', 'Mezarlıktaki ölülerin kendi ağzından yazılmış mezar yazılarıdır', ['Bir savaş gazisinin günlüğünden alınan notlardan oluşan kronolojik bir anı kitabıdır', 'Mektuplardan oluşur', 'Bir çocuk kahramanın büyüme öyküsüdür'], 'Ölüler, hayattayken gizledikleri sırları ve acıları kendi sözleriyle anlatır; kitap küçük kasaba yaşamının ikiyüzlülüğünü ortaya koyar.'),
  ('Robert Lowell ve Anne Sexton gibi şairlerle ilişkilendirilen \'itirafçı şiir\' anlayışının özelliği nedir?', 'Şairin özel yaşamını ve ruhsal bunalımlarını doğrudan şiire taşıması', ['Mitolojik kahramanları ve tanrıları yeniden yorumlayarak ve onlara yeni anlamlar yükleyerek anlatmaları', 'Siyasi propaganda yapması', 'Doğa betimlemelerini öne çıkarması'], 'İtirafçı şiir, 1950-60\'larda şairin kişisel acısını açıkça konu eden bir eğilimdir; Plath da bu çizgiyle anılır.'),
  ('Joseph Heller\'in \'Madde 22\' romanındaki \'Catch-22\' kuralının çelişkisi nedir?', 'Muafiyet isteyenin akıllı sayılıp muafiyet alamaması', ['Ordudan ayrılmak için üç yıl hizmet etme zorunluluğu getirilmesi', 'Her pilotun terfi için ölmesi gerekmesi', 'Subayların er olarak görev yapması'], 'Kural, delinin uçuştan muaf olacağını söyler; ama muafiyeti istemek akıl sağlığının kanıtıdır. Yossarian bu kısır döngüde sıkışır.'),
  ('Vonnegut\'un \'Mezbaha 5\' romanında Billy Pilgrim\'in zamanda sıçrayan yaşamı, yazarın hangi deneyimine dayanır?', 'İkinci Dünya Savaşı\'nda Dresden bombardımanından sağ çıkması', ['Pearl Harbor saldırısı sırasında donanmada subay olarak görev yapması', 'Kore Savaşı\'na katılması', 'Hiroşima\'yı ziyaret etmesi'], 'Vonnegut Dresden\'de esir iken bombardımana tanık oldu; romandaki \'Böyle gelmiş böyle gider\' tekrarı ölüm karşısındaki kabullenişi anlatır.'),
  ('Ralph Ellison\'ın \'Görünmez Adam\' romanındaki adsız anlatıcı neden \'görünmez\'dir?', 'Toplumun onu kimliğiyle değil, ırkına yönelik önyargılarıyla görmesi nedeniyle', ['Bilimsel bir deney geçirdiği için', 'Sürekli kaçtığı için', 'Yüzünü sakladığı için'], 'Siyah anlatıcı, beyaz toplum tarafından bir birey olarak algılanmaz; görünmezlik, ırkçılığın kimliği silişinin simgesidir.'),
  ('Truman Capote\'nin \'Soğukkanlılıkla\' kitabı hangi yeni türün öncüsü sayılır?', 'Gerçek bir cinayet olayını roman tekniğiyle anlatan \'kurgusal olmayan roman\'', ['Bilim kurgu', 'Anı edebiyatı', 'Absürd tiyatro'], 'Capote, Kansas\'taki Clutter ailesi cinayetini yıllarca araştırıp edebi bir kurguyla sundu; kitap yeni gazetecilik akımının dönüm noktası oldu.'),
  ('Cormac McCarthy\'nin \'Yol\' romanı hangi durumu anlatır?', 'Yıkıma uğramış bir dünyada hayatta kalmaya çalışan baba ve oğlunu', ['Uzay istasyonunda mahsur kalan iki astronotun hayatta kalma çabasını', 'Bir kasabadaki adaleti', 'Bir şirketin iflasını'], 'Romanda adı verilmeyen baba ve oğul, küllerle kaplı bir dünyada güneye doğru ilerler. Eser, umut ve yalın bir dil üzerine kuruludur.'),
  ('Allen Ginsberg\'in \'Uluma\' şiiri, hangi sözlerle başlar ve neyi dile getirir?', '\'Kuşağımın en iyi beyinlerinin çılgınlıkla yıkıldığını gördüm\'; Beat isyanı', ['\'Nisan ayların en zalimidir\'; savaş sonrası Avrupa\'nın manevi çöküşünü anlatan şiir', '\'Ben kendimi söylüyorum\'; demokrasi coşkusunu', '\'Ormanda iki yol ayrıldı\'; seçim güçlüğünü'], 'Ginsberg\'in uzun, soluksuz dizeleri, 1950\'lerin tüketim toplumuna ve baskıcı normlara başkaldıran bir kuşağın portresini çizer.'),
  ('Lawrence Ferlinghetti\'nin \'City Lights\' kitabevi Beat kuşağı için hangi rolü üstlenmiştir?', 'Kuşağın şiirlerini yayımlayıp topluluğun buluşma noktası olması', ['Beat yazarlarının eserlerini Avrupa\'ya dağıtan bir dergi dağıtım şirketi olması', 'Üniversite kütüphanesi olması', 'Devlet yayınevi olması'], 'San Francisco\'daki City Lights, Ginsberg\'in \'Uluma\'sını yayımladı; kitabevi aykırı edebiyatın merkezi oldu.'),
  ('Richard Wright\'ın \'Yerli Çocuk\' romanındaki Bigger Thomas\'ın trajedisi neyi eleştirir?', 'Yoksul siyah bir gencin çevresine ve ırkçı düzene mahkûmiyetini', ['Savaş sonrası yoksulluğu', 'Üniversite sistemini', 'Hapishane yönetimini'], 'Chicago\'daki gecekonduda yaşayan Bigger, bir kaza sonucu beyaz bir kızın ölümüne neden olur; roman, toplumsal koşulların suçu şekillendirişini gösterir.'),
  ('Alice Walker\'ın \'Mor Renk\' romanının biçimini belirleyen yapı nedir?', 'Celie\'nin Tanrı\'ya ve kız kardeşine yazdığı mektuplar', ['Bir mahkeme duruşmasının resmî tutanakları ve tanık ifadeleri', 'Gazete haberleri', 'Bir doktorun raporları'], 'Roman mektup biçimindedir; Celie\'nin sesiyle kadın dayanışması ve siyahi kadınların bastırılmışlığı anlatılır. Eser 1983\'te Pulitzer aldı.'),
  ('Shirley Jackson\'ın \'Piyango\' öyküsünde kasabalıların yıllık gelenekte taş atarak gerçekleştirdiği şey nedir?', 'Kurayla seçilen bir kasabalıyı taşlayarak öldürmek', ['Hayır işi için para toplamak', 'Yeni bir belediye başkanı seçmek', 'Hasat bayramı yapmak'], 'Sıradan bir gün gibi başlayan öykü, geleneğe körü körüne bağlılığın şiddetini sert bir ironiyle gösterir.'),
  ('Carver\'ın \'Katedral\' öyküsünde anlatıcıyı dönüştüren deneyim nedir?', 'Kör bir adamla birlikte katedral çizerek ilk kez içten iletişim kurması', ['Gotik bir katedrali gezerek mimariye hayran kalıp inancını yeniden bulması', 'Eşiyle barışması', 'Ölüm döşeğindeki dostunu ziyaret etmesi'], 'Önyargılı anlatıcı, kör konuğuyla çizim yaparken gözleri kapalı bir hâlde ilk kez bir şeyi \'görür\'; bu epifani öykünün doruk noktasıdır.'),
  ('Jack London\'ın \'Ateş Yakmak\' öyküsünde adamın ölümüne yol açan başlıca hata nedir?', 'Aşırı soğukta yerel uyarıları dinlemeyip tek başına yola çıkması', ['Kendi eşyalarını yitirmesi', 'Köpeğin kaçması', 'Haritayı yanlış okuması'], 'Doğaya meydan okuyan adamın aşırı özgüveni, doğalcı bir bakışla ölümüne giden süreci hazırlar.'),
  ('Sinclair Lewis hangi bakımdan Amerikan edebiyatı tarihinde bir ilktir?', '1930\'da Nobel Edebiyat Ödülü\'nü kazanan ilk Amerikalı yazar olması', ['Pulitzer\'i alan ilk yazar olması', 'Amerika\'da yayımlanan ilk romancı olması', 'Nobel\'i iki kez alan ilk yazar olması'], 'Lewis, \'Main Street\' ve \'Babbitt\' gibi romanlarıyla orta sınıf Amerikan yaşamını eleştirdi; Nobel\'i Amerikalılar arasında ilk o aldı.'),
  ('Upton Sinclair\'in \'Orman\' romanı yayımlandığında hangi sonucu doğurmuştur?', 'Chicago kesimhanelerindeki koşulların ifşa edilmesi ve gıda yasalarının çıkması', ['Göçmen işçi sendikalarının yasaklanması ve kesimhane sahiplerine devlet nişanı verilmesi', 'Et fiyatlarının düşmesi', 'Kanada sınırının kapatılması'], 'Romanda Litvanyalı göçmen işçilerin sömürüsü anlatılırken et paketleme sanayisindeki iğrenç koşullar da gözler önüne serildi; 1906\'da gıda ve ilaç yasaları çıktı.'),
  ('Isaac Bashevis Singer\'ın 1978\'de Nobel kazandığı eserleri hangi dilde yazılmıştır?', 'Yidiş', ['İbranice', 'İngilizce', 'Lehçe'], 'Polonya doğumlu Singer, ABD\'ye göç etse de eserlerini Yidişçe yazdı ve çevirileriyle tanındı.'),
  ('\'Amerikan Rüyası\' deyimini James Truslow Adams hangi anlamda yaygınlaştırmıştır?', 'Herkesin yeteneği ve çalışmasıyla daha iyi bir yaşama ulaşabileceği inancı', ['Herkesin eşit servete sahip olması', 'Güneye göçün teşvik edilmesi', 'Köleliğin sona ermesi'], 'Adams, 1931\'de \'The Epic of America\' kitabında fırsat eşitliği ve bireysel çabayla yükselme idealini bu terimle özetledi.'),
  ('Willa Cather\'in \'Ey Öncüler!\' romanı hangi çevreyi ve temayı işler?', 'Nebraska\'da İskandinav göçmen çiftçilerin toprağı işleme mücadelesi', ['Kaliforniya altın madenlerinde zengin olmaya çalışan göçmen işçilerin kamp yaşamı', 'New York borsası', 'Güney plantasyonları'], 'Alexandra Bergson\'un toprağa bağlılığı ve çabası, Amerikan sınırının kadın kahramanını gösterir.'),
  ('Fernández de Lizardi\'nin \'Periquillo Sarniento\' (Uyuz Papağan) romanı ne bakımdan tarihî önem taşır?', 'Latin Amerika\'da yazılan ilk roman olarak kabul edilmesi', ['Bağımsızlık Savaşı\'nın ilk şiiri olması', 'İlk tiyatro oyunu olması', 'İlk bilimsel inceleme olması'], '1816\'da yayımlanan roman, pikaresk geleneği Meksika toplumuna uyarlayarak sömürge düzenini hicveder.'),
  ('Domingo Faustino Sarmiento\'nun \'Facundo\' adlı yapıtı, uygarlık ile barbarlık karşıtlığını hangi toplumsal ayrım üzerinden işler?', 'Şehir ile kırsal bölgedeki gaucho yaşamı arasında', ['Doğu ile batı arasındaki ticaret yolu ve kıyı limanları arasındaki rekabet', 'Zenginlerle yoksullar arasında', 'Kilise ile devlet arasında'], 'Arjantinli Sarmiento, şehirli uygarlığı Avrupa modeline yaklaştırırken kırsalı barbarlık olarak niteledi; bu düşünce Latin Amerika\'da uzun süre tartışıldı.'),
  ('Latin Amerika\'da bağımsızlık sonrası yazarlar için \'mestizaje\' kavramı neyi ifade eder?', 'Yerli, Avrupalı ve Afrikalı unsurların karışmasından doğan kimlik', ['Yalnızca İspanyol soyunun saflığını ve üstünlüğünü savunan sömürge ideolojisi', 'Kıtanın bölünmesi', 'Sömürgecinin dilinden vazgeçme'], 'Mestizaje, kıtanın ırksal ve kültürel karışımını anlatır; edebiyat bu karışımı kimlik sorunu olarak işler.'),
  ('José Martí\'nin \'Bizim Amerikamız\' denemesi, Latin Amerika için hangi tutumu savunur?', 'Kıtanın kendi kimliğine ve özgün yönetim biçimine sahip çıkması', ['Avrupa\'nın yönetim modelini hiçbir değişiklik yapmadan kıtaya uygulamayı', 'ABD\'ye bağlanması', 'Kıtanın bölünmesi'], 'Küba\'nın bağımsızlık önderi Martí, kıtanın kendi tarihini bilmesi gerektiğini ve dışarıdan alınan kalıplarla yönetilemeyeceğini savundu.'),
  ('Leopoldo Lugones\'in Latin Amerika\'ya kazandırdığı edebiyat türü nedir?', 'Fantastik öykü', ['Destan', 'Pastoral şiir', 'Mektup romanı'], 'Arjantinli Lugones, \'Garip Güçler\' gibi öykülerle Latin Amerika fantastik edebiyatının öncülerinden olmuştur.'),
  ('Horacio Quiroga\'nın öykülerinde sık işlenen tema hangisidir?', 'Doğanın vahşi gücü karşısında insanın çaresizliği', ['Şehir yaşamının sıkıcılığı', 'Aşk üçgenleri', 'Savaş kahramanlıkları'], 'Uruguaylı Quiroga, Misiones ormanında yaşadı; \'Orman Öyküleri\' gibi kitaplarında hayvanları ve doğayı acımasız bir gerçekçilikle anlattı.'),
  ('Borges\'in \'Funes Hafızalı\' öyküsünde Ireneo Funes\'in talihsizliği nedir?', 'Hiçbir şeyi unutamaması ve bu yüzden soyut düşünememesi', ['Hafızasını bir kazada kaybetmesi ve geçmişini hatırlayamaması', 'Çok yaşlanıp kör olması', 'Bilgiyi hızlı unutarak her gün yeniden öğrenmesi'], 'Funes her ayrıntıyı hatırlar ama genelleme yapamaz; öykü, düşünmenin unutma ve soyutlama gerektirdiğini ima eder.'),
  ('Borges\'in \'Dairesel Harabeler\' öyküsündeki büyücünün sonunda fark ettiği şey nedir?', 'Kendisinin de bir başkasının düşü olduğunu', ['Büyüsünün tükenmesi ve yarattığı adamın kendisini terk ettiğini', 'Harabelerin hazine sakladığını', 'Ölümsüz olduğunu'], 'Rüyasında bir adam yaratan büyücü, sonunda kendisinin de bir başkasının düşünde var olduğunu anlar; bu, gerçekliğin güvensizliği temasıdır.'),
  ('Borges\'in öykülerinde labirent ve ayna imgelerinin sıkça yer almasının nedeni nedir?', 'Gerçekliğin sonsuz ve yanıltıcı doğasını simgelemeleri', ['Mimarlık eğitimi almış olması ve kentlerin planına duyduğu merak', 'Çocukluk anıları', 'Sirk kültürü'], 'Labirent, sonsuzluk ve belirsizlik; ayna ise insanın ve gerçekliğin çoğalması fikrini temsil eder.'),
  ('Borges\'in \'Çatallanan Yollar Bahçesi\' öyküsünde kitabın yapısı hangi fikre dayanır?', 'Zamanın tek çizgi yerine dallanarak ilerlemesi', ['Sonsuz tekrar eden ve hiçbir zaman değişmeyen bir döngü', 'Zamanın durması', 'Geçmişin silinmesi'], 'Ts\'ui Pên\'in romanı, her olayda olasılıkların dallanıp paralel evrenler yarattığı bir zaman kuramını yansıtır.'),
  ('Neruda\'nın gerçek adı nedir ve \'Neruda\' takma adını hangi şaire borçludur?', 'Neftalí Ricardo Reyes; Çek yazar Jan Neruda\'ya', ['Pablo Neruda Garay; Çek şair Vítězslav Nezval\'a', 'Ricardo Eliécer Neftalí; Polonyalı yazar Reymont\'a', 'Neftalí Reyes Neruda; Rus şair Nekrasov\'a'], 'Neruda, ailesinin şiir yazmasına karşı çıkması nedeniyle takma ad aldı; adın kaynağı Çek yazar Jan Neruda sayılır.'),
  ('Neruda\'nın \'Canto General\' adlı yapıtı hangi amaca hizmet eder?', 'Latin Amerika\'nın doğasını, halkını ve tarihini epik bir şiirle anlatmak', ['Bir aşk hikâyesini ve şairin sevgilisine yazdığı mektupları şiirle anlatmak', 'Meksika Devrimi\'ni belgelemek', 'Şili\'nin yasalarını yazıya dökmek'], 'Canto General, kıtanın yerli kökenlerinden sömürge dönemine, bağımsızlık mücadelesinden çağdaş sömürüye uzanan geniş bir şiirdir.'),
  ('Neruda\'nın İspanya İç Savaşı\'nı yaşadıktan sonra şiirinde ortaya çıkan değişim nedir?', 'Daha çok siyasal ve toplumsal bilinç taşımaya başlaması', ['Şiiri tümüyle bırakıp roman ve tiyatro yazmaya yönelmesi ve yurda dönmesi', 'Dinî temalara yönelmesi', 'Yalnızca doğa şiirleri yazması'], '\'Yüreğimde İspanya\' kitabı, şairin bireysel kaygılardan halkın acısına yönelişini gösterir.'),
  ('Octavio Paz\'ın \'Yalnızlık Labirenti\' adlı denemesi hangi konuyu inceler?', 'Meksikalıların kimliği, maskeleri ve tarihle ilişkisini', ['Avrupa\'daki göçmenlerin durumunu', 'Bilimsel devrimleri', 'Dinî mezhepleri'], 'Paz, Meksika\'nın tarihsel ve psikolojik kimliğini analiz eder; kitap Latin Amerika düşüncesinin önemli denemelerindendir.'),
  ('Gabriela Mistral\'in gerçek adı nedir?', 'Lucila Godoy Alcayaga', ['Gabriela Reyes Basoalto Neruda', 'Lucila Reyes', 'Isabel Mistral'], 'Mistral takma adını İtalyan şair Gabriele D\'Annunzio ile Fransız şair Frédéric Mistral\'e saygıdan almıştır; öğretmenlik yaptı ve çocuk eğitimine önem verdi.'),
  ('Nicolás Guillén\'in şiirinde öne çıkan özellik nedir?', 'Afrika kökenli Küba müziğinin ritmini şiire taşıması', ['Eski Yunan ölçülerini ve mitolojik göndermeleri yeniden kullanması', 'Fransız sembolizmini taklit etmesi', 'İspanya\'nın klasik şiirini sürdürmesi'], 'Guillén, \'Son\' ve Afro-Küba ritimlerini şiire uyarlayarak siyah Küba kültürünü yücelten bir şiir yarattı.'),
  ('\'Kolera Günlerinde Aşk\'ta Florentino Ariza\'nın Fermina Daza\'ya olan sevgisi ne kadar süre sonra sonuçlanır?', 'Yaklaşık elli yıl sonra, Fermina\'nın kocası ölünce', ['Üç yıl sonra', 'On yıl sonra', 'Yalnızca bir yıl sonra'], 'Florentino, elli bir yıl dokuz ay dört gün boyunca Fermina\'ya olan sevdasını sürdürür; roman, sadakatin zaman karşısındaki gücünü işler.'),
  ('\'Patriğin Sonbaharı\' romanının biçimsel özelliği nedir?', 'Uzun cümleler ve topluluğun sesinden anlatım', ['Kısa diyaloglar ve tiyatro sahneleri biçiminde yazılması', 'Mektuplardan oluşması', 'Şiir biçiminde yazılması'], 'Roman, yaşlı bir diktatörün yaşamını noktalamasız uzun paragraflarda, halkın ağzından aktarır.'),
  ('Yüzyıllık Yalnızlık\'ta çingene Melquíades\'in bıraktığı parşömenlerin anlamı en sonda nasıl açıklanır?', 'Buendía ailesinin tüm tarihinin önceden yazılmış olması', ['Gömülü bir hazinenin yerini gösteren şifreli bir harita olması', 'Bir ilaç tarifi olduğu anlaşılır', 'Aileye bir lanet okuduğu anlaşılır'], 'Aureliano Babilonia parşömenleri çözdüğünde ailenin kaderini okur; okuduğu anda Macondo rüzgârla yok olur.'),
  ('Sihirli gerçekçilikte olağanüstü olayların sunuluş biçimi nasıldır?', 'Gündelik olaylar gibi ciddi ve şaşırmadan anlatılır', ['Yazarın uzun açıklamalarıyla ve bunların rüya olduğu belirtilerek', 'Korku ve gerilim yaratılarak', 'Yalnızca çocuk karakterlerin sözleriyle'], 'Okur, olağanüstü olayları gündelik olaylar gibi anlatan sakin bir ses duyar; bu tutum sihirli gerçekçiliği fantastikten ayırır.'),
  ('Vargas Llosa\'nın \'Katedralde Konuşma\' romanı hangi dönemi eleştirir?', 'Peru\'daki Odría diktatörlüğünü', ['İspanyol sömürge yönetimini ve engizisyonu', 'Fidel Castro dönemini', 'Sandinista rejimini'], 'Roman, iki arkadaşın bir barda konuşmasıyla 1950\'lerin Peru\'sundaki yozlaşmış diktatörlüğü ve toplumu anlatır.'),
  ('Latin Amerika \'Boom\' kuşağının uluslararası yükselişinde etkili olan Barselonalı edebiyat ajanı kimdir?', 'Carmen Balcells', ['Simone de Beauvoir', 'Gertrude Stein', 'Victoria Ocampo'], 'Balcells, García Márquez, Vargas Llosa ve Donoso gibi yazarların temsilciliğini yaparak Boom\'un Avrupa\'da tanınmasına yardımcı oldu.'),
  ('Cortázar\'ın \'Axolotl\' öyküsünde anlatıcının başına gelen olay nedir?', 'Akvaryumdaki aksolotl\'a bakarken onunla yer değiştirmesi', ['Hayvanat bahçesinde kaybolması', 'Bir hayvanın saldırısı', 'Bir bilim insanının deneyi'], 'Anlatıcı, aksolotlun gözlerine saplanıp kalır ve bir noktada kendini akvaryumun içinde bulur; öykü kimlik ve öteki olma temalarını işler.'),
  ('Juan Rulfo\'nun \'Yanan Ova\' öykü kitabı hangi toplumsal gerçeği yansıtır?', 'Devrim sonrası kırsal bölgelerdeki yoksulluğu ve umutsuzluğu', ['Büyük şehirlerdeki lüks yaşamı ve burjuva eğlencelerini anlatan bir gerçeklik', 'Okyanus yolculuklarını', 'Sanayi grevlerini'], 'Rulfo, Jalisco kırsalındaki kuraklık, şiddet ve yalnızlıkla örülü yaşamı sade ve yoğun bir dille anlatır.'),
  ('Carlos Fuentes\'in \'Aura\' adlı kısa romanı hangi türün örneği sayılır?', 'Fantastik ve gotik anlatı', ['Tarihî roman türünden bir yapıt', 'Polisiye roman', 'Savaş romanı'], 'Genç tarihçi Felipe Montero\'nun yaşlı bir dul kadının evinde çalışırken karşılaştığı doğaüstü olaylar, zaman ve kimlik karışımını işler.'),
  ('\'Magischer Realismus\' terimini ilk kez 1925\'te hangi alanda kullanan Franz Roh\'un mesleği nedir?', 'Alman sanat eleştirmeni', ['İspanyol edebiyat tarihçisi', 'Fransız romancı', 'Arjantinli tarihçi'], 'Roh, terimi Yeni Nesnellik dönemi resmi için kullandı; terim edebiyata sonradan geçti ve Latin Amerika romanıyla özdeşleşti.'),
  ('Asturias 1967\'de Nobel Edebiyat Ödülü\'nü aldığında eserlerinin hangi yönü öne çıkarılmıştır?', 'Yerli halk geleneklerine ve Maya mitlerine dayanan yaratıcı anlatımı', ['Siyasi gazeteciliği', 'Tarihî belgelere bağlılığı', 'Avrupa klasiklerine yakınlığı'], 'Asturias, \'Mısır Adamları\' gibi eserlerinde Maya mitolojisini ve yerli bakış açısını modern anlatıya katmıştır.'),
  ('Sihirli gerçekçiliği fantastik edebiyattan ayıran temel fark nedir?', 'Olağanüstü olay gerçekliğin doğal bir parçası gibi sunulur', ['Olağanüstü olay yalnızca rüya ya da halüsinasyon olarak sunulur', 'Yalnızca çocuklara yönelik yazılır', 'Tarihle hiçbir ilgisi yoktur'], 'Fantastikte olağanüstü bir ihlal sayılan olay, sihirli gerçekçilikte hiçbir şaşkınlık uyandırmadan olağan akışın içinde kalır.'),
  ('João Guimarães Rosa\'nın \'Büyük Sertão: Patikalar\' romanında Riobaldo\'yu endişelendiren soru nedir?', 'Şeytanla anlaşma yapıp yapmadığı', ['Gömülü hazinenin yerinin bulunması', 'Kardeşinin ölümü', 'Bir cinayetin faili'], 'Eski haydut Riobaldo, yaşadığı çatışmalar ve kuşkular sırasında iyilik ile kötülük, Tanrı ile şeytan sorularını sorgular.'),
  ('Euclides da Cunha\'nın \'Os Sertões\' adlı yapıtı hangi olayı hem gazeteci hem bilim insanı gözüyle anlatır?', 'Canudos ayaklanması ve onun bastırılması', ['Köleliğin kaldırılmasından sonraki toplumsal bunalım', 'Cumhuriyetin ilanı', 'Amazon seferi'], 'Kitap, Brezilya ordusunun 1897\'de Canudos topluluğunu yok edişini belgesel ve edebî bir dille aktarır.'),
  ('Isabel Allende\'nin \'Paula\' adlı kitabı ne tür bir yapıttır?', 'Komadaki kızı için yazdığı anı niteliğinde aile öyküsü', ['Tarih kitabı', 'Çocuk romanı', 'Bilimkurgu romanı'], 'Allende, hasta yatağındaki kızına aile geçmişini anlatır; kitap yazarın kendi yaşamını ve Şili tarihini içeren bir anıdır.'),
  ('Victoria Ocampo\'nun Latin Amerika edebiyatındaki rolü nedir?', 'Sur dergisini kurup yazarları çevirip desteklemesi', ['Bağımsızlık Savaşı\'nda süvari komutanı olarak görev alması', 'Bağımsızlık Savaşı\'nda komutanlık yapması', 'İlk tiyatro oyununu sahnelemesi'], 'Arjantinli Ocampo, Sur dergisiyle Latin Amerika\'yı Avrupa ve Amerikan edebiyatına açtı; Borges ve Cortázar\'ın yayımlanmasında önemli bir destekçiydi.'),
  ('Elena Poniatowska\'nın \'Tlatelolco Gecesi\' kitabı hangi türde yazılmıştır?', 'Tanıklıklardan oluşan belgesel anlatı', ['Tarihî roman', 'Epik şiir', 'Bilimkurgu'], 'Kitap, 1968\'de Mexico City\'de öğrenci gösterisine yönelik katliama ilişkin tanıklıkları bir araya getirir.'),
  ('Augusto Roa Bastos\'un \'Ben, Yüce\' romanı hangi ülkenin hangi yöneticisini konu alır?', 'Paraguay\'ın diktatörü Doktor Francia\'yı', ['Arjantin\'in federal lideri general Rosas\'ı', 'Şili\'nin başkanı Allende\'yi', 'Meksika\'nın dikta yöneticisi Díaz\'ı'], 'Roman, 19. yüzyıl Paraguay\'ında ülkeyi dış dünyadan koparan Francia\'nın sözde belgeler ve monologlarla yeniden kurulmuş portresini sunar.'),
  ('Julia Alvarez\'in \'Kelebeklerin Zamanı\' romanı hangi gerçek kişileri anlatır?', 'Trujillo diktatörlüğüne direnen Mirabal kardeşleri', ['Meksika Devrimi\'nde savaşan kadın askerlerin hayatını', 'Şili\'deki darbeden kaçan sanatçıları', 'Küba\'dan göç eden aileleri'], 'Dominik Cumhuriyeti\'nde \'Kelebekler\' lakabıyla bilinen dört kız kardeşten üçü 1960\'ta öldürülmüştür; roman onların yaşamını kurmacayla anlatır.'),
  ('Ariel Dorfman\'ın \'Ölüm ve Kız\' oyununda Paulina\'nın evinde karşılaştığı adam neden önemlidir?', 'Diktatörlük döneminde işkence eden doktoru olabileceğine inanması', ['Eski bir sevgilisi olması', 'Evin yeni sahibi olması', 'Bir ünlü müzisyen olması'], 'Oyun, geçmişin suçlarıyla yüzleşme, adalet ve intikam arasındaki ikilemi ele alır; Schubert\'in aynı adlı yapıtına gönderme içerir.'),
  ('Diktatör romanları, Latin Amerika\'da otoriter yönetimlere karşı hangi işlevi görmüştür?', 'Baskıyı ve korkuyu ortak belleğe yazarak eleştirmek', ['Diktatörleri övüp halkı yönetime ısındırmaya çalışmak', 'Askerî stratejileri öğretmek', 'Kıtanın ekonomisini planlamak'], 'Bu romanlar, iktidarın mekanizmalarını abartı, mizah ve kâbus havasıyla yansıtır; yazarlar çoğu zaman sürgüne gitmiştir.'),
  ('Ernesto Sábato\'nun \'Tünel\' romanında ressam Juan Pablo Castel\'in ana saplantısı nedir?', 'Kendisini anladığını sandığı María\'ya duyduğu takıntılı aşk', ['Bir ödüle ulaşmak', 'Bir tabloyu sattırmak', 'Bir kasabaya sığınmak'], 'Castel, María\'yı öldürdükten sonra olayı yalnızlığın ve iletişimsizliğin ürünü olarak anlatır; roman varoluşçu bir psikolojik inceleme olarak bilinir.'),
  ('Roberto Bolaño\'nun \'Vahşi Hafiyeler\' romanında şairlerin oluşturduğu grubun adı nedir?', 'Visceral Realistler', ['Kayıp Kuşak şairleri', 'Beat Şairleri', 'Sembolist Çember'], 'Roman, Meksika\'da bir şair grubunun kayıp bir şairi arayışını farklı anlatıcılarla anlatır; Bolaño\'nun 2666\'sı da ölümünden sonra yayımlanmıştır.'),
  ('Eduardo Galeano\'nun \'Latin Amerika\'nın Kesik Damarları\' kitabı hangi iddiayı ileri sürer?', 'Kıtanın yoksulluğunun uzun süren sömürü ve dış bağımlılıktan kaynaklandığını', ['Kıtanın yoksulluğunun doğal nedenlerden kaynaklandığını', 'Yerli halkların tarım bilmediğini', 'Sömürgeciliğin ekonomiye yararlı olduğunu'], '1971 tarihli kitap, İspanyol sömürgeciliğinden günümüz çokuluslu şirketlerine uzanan tarihsel sömürü zincirini anlatan bir tarih-deneme karışımıdır.'),
  ('José Lezama Lima\'nın \'Paradiso\' romanı hangi estetik anlayışla anılır?', 'Neo-barok', ['Doğalcılık', 'Sosyalist gerçekçilik', 'Minimalizm'], 'Küba\'lı Lezama Lima\'nın yoğun imgeli, ağır dokulu üslubu Latin Amerika neo-barok geleneğinin başyapıtı olarak görülür.'),
  ('Nobel alan Latin Amerikalı yazarların ortak noktası olarak aşağıdakilerden hangisi söylenebilir?', 'Kıtanın tarihi ve toplumsal gerçekliğini eserlerinde işlemeleri', ['Tümünün Avrupa\'da doğup sonradan Latin Amerika\'ya göç etmiş olması', 'Tümünün yalnızca şiir yazması', 'Tümünün yalnız tiyatro yazması'], 'Mistral, Asturias, Neruda, García Márquez, Paz ve Vargas Llosa kıtanın kimliği, tarihi ve siyasal sorunlarını eserlerinde işlemiştir.'),
  ('García Márquez ve Vargas Llosa\'nın 1976\'da sonlanan dostluğu hangi nedenle anılır?', 'Aralarındaki kişisel ve siyasi anlaşmazlık', ['Ortak bir kitapta çalışıp kitabın paylaşımı konusunda çekişmeleri', 'Aynı ödülü paylaşmaları', 'Aynı şehirde doğmaları'], 'İki yazar, uzun süre arkadaşken kişisel ve siyasi gerekçelerle araları açıldı; bu olay Boom kuşağının en bilinen kırgınlıklarındandır.'),
  ('Walther von der Vogelweide\'yi Minnesänger\'ler arasında ayıran özellik nedir?', 'Aşk şiirlerinin yanında siyasi konulara da eğilmesi', ['Yalnızca dinî ilahiler yazıp aşk şiirinden uzak durması', 'Tüm şiirlerinde kralı övmesi', 'Yalnızca halk masalları derlemesi'], 'Walther, imparator ile papa arasındaki çekişme gibi güncel konuları da şiirine taşıyan \'Spruch\' şiirleriyle tanınır.'),
  ('Nibelungen Destanı\'nda Siegfried\'in öldürülmesine imkân veren zayıf noktası nasıl oluşmuştur?', 'Ejderha kanında yıkanırken omuzlarına yapışan bir ağaç yaprağı yüzünden', ['Çocukken aldığı bir yara yüzünden', 'Büyülü bir kılıcı kaybettiği için', 'Sihirli bir pelerin yüzünden'], 'Siegfried\'in sırtında bir yaprak vücuda kanın değmesini engellemiş, Hagen bu noktaya mızrak saplayarak onu öldürmüştür.'),
  ('Martin Luther\'in 1522\'de Wartburg\'da çevirdiği Yeni Ahit\'in Alman edebiyatına katkısı nedir?', 'Farklı lehçeleri bir araya getirerek ortak bir yazı dilinin oluşmasına yardım etmesi', ['Latince edebiyatı kalıcı hale getirmesi', 'Şiirsel ölçüyü kaldırması', 'Tiyatroyu yasaklaması'], 'Luther\'in halkın anlayacağı bir dille yaptığı çeviri, standart Almancanın biçimlenmesinde dönüm noktası oldu.'),
  ('Alman Barok şiirinde sık işlenen \'vanitas\' ve \'memento mori\' temaları hangi düşünceyi dile getirir?', 'Dünyevi şeylerin geçiciliğini ve ölümün kaçınılmazlığını', ['Savaşın zaferini', 'Aşkın sonsuzluğunu', 'Bilimin ilerleyişini'], 'Otuz Yıl Savaşları\'nın yarattığı yıkım, Gryphius gibi şairlerin dizelerinde geçicilik ve ölüm düşüncesini öne çıkardı.'),
  ('Lessing\'in \'Minna von Barnhelm\' komedisinin tarihî arka planı nedir?', 'Yedi Yıl Savaşları sonrası bir subayın onuru ve aşk', ['Haçlı seferleri sonrası şövalyelerin yurda dönüşü ve miras kavgası', 'Fransız Devrimi', 'Otuz Yıl Savaşları'], 'Oyun, savaştan sonra işsiz ve yoksul kalan Binbaşı Tellheim\'ın onur anlayışı ile nişanlısı Minna\'nın sevgisi çevresinde gelişir.'),
  ('Lessing\'in \'Laokoon\' adlı kuramsal yapıtı hangi soruyu tartışır?', 'Resim ile şiirin ifade sınırlarının farklı olduğunu', ['Tiyatronun dinle ilişkisini', 'Dilin kökenini', 'Mimarinin tarihini'], 'Lessing, resmin uzamda, şiirin zamanda ilerlemesi nedeniyle farklı konulara uygun olduğunu savunur.'),
  ('Lessing\'in \'burjuva trajedisi\' (bürgerliches Trauerspiel) anlayışı neyi savunur?', 'Trajedi kahramanının soylu olmak zorunda olmadığını', ['Trajedinin yalnızca krallarla ilgili olması gerektiğini', 'Trajedinin komediyle birleşmesi gerektiğini', 'Trajedinin yok edilmesi gerektiğini'], 'Lessing, soylu olmayan kahramanların da seyirciyi etkileyebileceğini savunarak Alman sahne yazarlığını yeniledi.'),
  ('Wieland\'ın \'Agathon\' romanı hangi roman türünün öncüsü sayılır?', 'Gelişim romanı', ['Polisiye roman', 'Tarihî roman', 'Epistolar roman'], 'Agathon, genç bir kahramanın ruhsal gelişimini izleyen ilk Alman romanlarından biridir ve Goethe\'nin Wilhelm Meister\'ine zemin hazırlamıştır.'),
  ('Herder\'in halk şarkılarını derleyip \'Volkslied\' kavramını yaygınlaştırması hangi sonuca yol açmıştır?', 'Halk şiirine ilginin artması ve Romantizmi hazırlaması', ['Şiirin tümüyle yasaklanması ve yalnızca nesre izin verilmesi', 'Latince eğitimin zorunlu olması', 'Tiyatroların kapatılması'], 'Herder, halkın şiirinin ulusun ruhunu yansıttığını savundu; bu görüş Goethe\'yi ve romantikleri etkiledi.'),
  ('\'Sturm und Drang\' adı hangi yapıttan gelmektedir?', 'Klinger\'in 1776 tarihli oyunundan', ['Goethe\'nin 1774 tarihli Werther romanından', 'Schiller\'in Haydutlar\'ından', 'Lessing\'in Emilia Galotti\'sinden'], 'Friedrich Maximilian Klinger\'in \'Sturm und Drang\' oyununun adı, 1770\'lerde Aydınlanma akılcılığına karşı çıkan edebî harekete verilmiştir.'),
  ('Schiller\'in \'Haydutlar\' oyunundaki Karl Moor\'un haydut olmasına yol açan şey nedir?', 'Kardeşinin oyunlarıyla babasının gözünden düşmesi', ['Ordudan atılıp rütbesinin ve nişanlarının elinden alınması', 'Bir aşkın kaybı', 'Bir hazinenin bulunması'], 'Karl Moor, kardeşi Franz\'ın entrikaları yüzünden evinden kopup haydut çetesinin başına geçer; oyun adalet ve özgürlük arayışını işler.'),
  ('Goethe ile Schiller\'in 1794\'te başlayan dostluğunun edebiyata katkısı nedir?', 'Karşılıklı eleştiriyle Alman klasisizminin en verimli dönemini yaratmaları', ['Ortak bir ansiklopedi yazmaları', 'Bir tiyatro okulu kurmaları', 'Savaş sırasında sürgüne gitmeleri'], 'İki şair, birbirlerinin eserlerini destekleyip tartıştılar; baladlar yarışı ve ortak epigramlar (Xenien) bu ortaklığın ürünleridir.'),
  ('Goethe\'nin \'İtalya Yolculuğu\' kitabının onun sanat anlayışı bakımından önemi nedir?', 'Antik sanatla karşılaşmasının klasisizmi pekiştirmesi', ['Hıristiyan misyonerliğe yönelip rahip olmaya karar vermesi', 'Gotik mimariyi benimsemesi', 'Savaş anılarını kaleme alması'], 'Goethe 1786-88\'de İtalya\'yı gezerek Antik sanata hayran kaldı; bu deneyim, Sturm und Drang\'dan klasisizme geçişini belirledi.'),
  ('Goethe\'nin \'Seçilmiş Akrabalıklar\' romanının adı hangi bilimsel kavramdan alınmıştır?', 'Kimyadaki element ilgisi (afinite) kavramından', ['Fizikteki yerçekimi ve ağırlık kavramlarının etkisinden', 'Biyolojideki evrimden', 'Astronomideki kütle çekiminden'], 'Romanda evli iki çiftin beklenmedik çekimleri, kimyasal elementlerin birbirini seçici biçimde çekmesine benzetilir.'),
  ('Goethe\'nin \'Ormankralı\' baladında çocuğu neden ölür?', 'Baba atıyla dörtnala giderken oğlu ormankralının çağrısını duyup korkudan can verir', ['Kurt saldırısı yüzünden', 'Kış soğuğu yüzünden', 'Hastalık yüzünden'], 'Baba hiçbir şey duymaz, ama çocuk ormankralının çağrılarını duyar ve evlerine varıldığında ölmüş bulunur; balad doğaüstü korkuyu işler.'),
  ('Goethe\'nin \'Egmont\' oyunu hangi müzik eseriyle de bilinir?', 'Beethoven\'ın Egmont Uvertürü', ['Mozart\'ın Requiem adlı ölü ayini eseri', 'Haydn\'ın Yaratılış\'ı', 'Brahms\'ın Alman Requiem\'i'], 'Beethoven, Goethe\'nin Flaman kont Egmont\'un Habsburg zulmüne karşı direnişini ve idamını anlatan oyunu için sahne müziği besteledi.'),
  ('Goethe\'nin \'Iphigenie\' oyununda başkahramanın ünlü eylemi nedir?', 'Aldatmak yerine doğruyu söyleyip kralı ikna etmesi', ['Kralı gizlice zehirleyerek kardeşiyle birlikte kaçması', 'Kardeşini öldürmesi', 'Tanrılara kurban sunması'], 'Iphigenie, aldatmaya başvurmak yerine açık yüreklilikle insanlığa seslenir; oyun klasisizmin insani ideallerini yansıtır.'),
  ('Goethe\'nin \'Faust\' ikinci bölümünün birinci bölümden farkı nedir?', 'Daha simgesel, mitolojik ve felsefi bir yapıda olması', ['Tamamen gerçekçi bir günlük olması', 'Yalnızca aşk öyküsü olması', 'Düzyazı biçiminde olması'], 'İkinci bölümde Faust siyasete, antik dünyaya ve Helena ile birleşmeye yönelir; çok katmanlı bir alegoridir.'),
  ('Schiller\'in \'Entrika ve Aşk\' oyununun başlıca çatışması nedir?', 'Soylu genç ile burjuva kızının aşkının sınıf engeline çarpması', ['İki komşu ülke arasındaki sınır savaşı ve barış anlaşması tartışmaları', 'Bir mirası bölüşme', 'Bir din farkı'], 'Ferdinand ile Luise\'nin aşkı, saray entrikaları ve sınıf farkı yüzünden zehirlenmeyle sonuçlanır; oyun Sturm und Drang\'ın burjuva trajedisi örneğidir.'),
  ('Schiller\'in \'Maria Stuart\' oyununda iki kraliçenin karşılaşması kimler arasındadır?', 'İskoçya Kraliçesi Maria ile İngiltere Kraliçesi Elizabeth', ['Fransa Kraliçesi Katerina ile İspanya Kraliçesi İzabella\'nın', 'Cleopatra ile Roma imparatoru', 'Jeanne d\'Arc ile İngiltere Kralı'], 'Oyun, hapsedilmiş Maria\'nın Elizabeth\'le yüz yüze gelişini, iki kadının siyasi ve duygusal çatışmasını işler.'),
  ('Schiller\'in \'İnsanın Estetik Eğitimi Üzerine Mektuplar\' yapıtında savunduğu düşünce nedir?', 'Güzellik ve oyun yoluyla insanın özgürleşmesi', ['Savaşın ve zorbalığın insanı eğiten en iyi yol olduğu', 'Devletin sanatı denetlemesi', 'Bilimin sanatın yerini alması'], 'Schiller, estetik eğitimin bireyi hem duygu hem akıl bakımından bütünlediğini ve özgür bir topluma hazırladığını savundu.'),
  ('Schiller\'in \'Haydutlar\'ının yayımlandığı yıllarda Alman edebiyatına etkisi nasıl açıklanabilir?', 'Gençlerin yönetim ve toplumsal düzen karşısındaki başkaldırısının simgesi olmuştur', ['Yöneticilerce ödüllendirilmiştir', 'Dinî kurumlarca benimsenmiştir', 'Yalnızca çocuk edebiyatına girmiştir'], 'Oyun, genç Schiller\'in baskıcı bir düzene karşı duyduğu öfkeyi yansıttı; seyircide büyük coşku uyandırdı.'),
  ('Schiller\'in \'Saf ve Duygusal Şiir Üzerine\' denemesinde \'saf\' şair kime denir?', 'Doğayla uyum içinde yazan, Goethe gibi şair', ['Doğadan kopmuş olup yitirdiği uyumu özlemle arayan şair', 'Yalnızca Antik dönem şairi', 'Dinsel şair'], 'Schiller, doğal olanı olduğu gibi yansıtan şairi \'saf\', doğadan kopmuş olup onu arayanı \'duygusal\' diye tanımladı; kendini ikinci gruba koydu.'),
  ('Weimar Dükü Karl August ile Goethe\'nin ilişkisi nasıldır?', 'Dükün danışmanı ve bakanı olarak uzun yıllar görev yaptı', ['Dük, Goethe\'yi hükümet karşıtı yazılarından dolayı sürgüne gönderdi', 'Goethe, dükü savaşta öldürdü', 'Goethe, dükün düşmanı olarak Paris\'e kaçtı'], 'Goethe 1775\'te Weimar\'a gelip dükün yakın çalışma arkadaşı oldu; devlet işleri ve tiyatro yönetimiyle ilgilendi.'),
  ('Caspar David Friedrich\'in \'Bulutlar Denizi Üzerinde Gezgin\' gibi tabloları Romantik edebiyatla hangi ortak noktayı paylaşır?', 'Bireyin doğa karşısında duyduğu hayranlık ve yücelik', ['Siyasi propaganda ve devlet büyüklerinin yüceltilmesi', 'Sanayi devrimi sevinci', 'Antik kahramanlar'], 'Romantik resim ve şiir, insanı ulu doğa karşısında küçük ama duyarlı bir varlık olarak resmeder.'),
  ('E. T. A. Hoffmann\'ın birçok öyküsünde \'çifte yaşam\' ve \'gerçekle hayalin iç içe geçmesi\' teması neden dikkat çeker?', 'Romantik edebiyatta bilinçdışı ve gizemli olanın keşfini yansıttığı için', ['Çocukların eğitimini anlattığı için', 'Matematik ödevi olduğu için', 'Siyasi tarih kitabı olduğu için'], 'Hoffmann\'ın karanlık ve fantastik anlatıları ruhun bilinmeyen alanlarını keşfeder; sonradan psikanaliz ve gotik edebiyatı etkilemiştir.'),
  ('\'Genç Almanya\' hareketinin amacı nedir?', 'Edebiyatı özgürlük, siyasal katılım ve sansür karşıtlığının aracı kılmak', ['Romantizmi yüceltmek', 'Orta Çağ\'a dönüş', 'Yalnızca şiiri geliştirmek'], 'Heine, Börne ve Gutzkow gibi yazarlar 1830\'larda siyasal özgürlük için yazdılar; Alman Federasyonu 1835\'te yazılarını yasakladı.'),
  ('Georg Büchner\'in \'Danton\'un Ölümü\' oyunu Fransız Devrimi\'ne nasıl bakar?', 'Devrimin kendi çocuklarını yiyen karamsar yüzünü gösterir', ['Devrimi bütün yönleriyle över ve kusursuz bir zafer olarak idealleştirir', 'Krallığı savunur', 'Savaş zaferini anlatır'], 'Oyunda Danton ile Robespierre\'in çatışması, devrimin ideallerinin şiddete dönüşmesini ve bireyin tarih karşısındaki çaresizliğini gösterir.'),
  ('Büchner\'in \'Hessen Haberci\'si broşürünün temel çağrısı nedir?', '\'Saraylara savaş, kulübelere barış\'', ['\'Kilisenin yeniden inşası ve rahiplere itaat\'', '\'Krallara tam itaat\'', '\'Sanayiye ağırlık\''], '1834\'te yayımlanan bildiri, Hessen köylüsünü ezen soylulara karşı ayaklanmayı çağırır; yazar tutuklanmaktan kaçmak için ülkeyi terk etti.'),
  ('Büchner\'in \'Leonce ve Lena\' oyunu hangi türdedir?', 'Romantik komedi ve hiciv', ['Savaş trajedisi', 'Kutsal drama', 'Tarihî destan'], 'Birbirini tanımadan evlenmeye zorlanan prens ve prensesin kaçıp aşık olmasını anlatan oyun, saray hayatını hicveder.'),
  ('Heine\'nin \'Sen bir çiçek gibisin\' dizesiyle başlayan şiirinde şairin üslubunu tanımlayan özellik nedir?', 'Sade sevgi anlatımının hafif ironi ve hüzünle birleşmesi', ['Ağır felsefi sorgulama ve uzun, soyut metafizik tartışmalar', 'Savaş çağrısı', 'Dinî öğretiler'], 'Heine\'nin lirik şiiri, halk şarkısına yakın yalınlığıyla Romantizmin duygusallığını ve ironik kırılmayı bir arada taşır.'),
  ('Fontane\'nin \'Effi Briest\' romanında Effi\'nin yıkımına yol açan olay nedir?', 'Yıllar sonra bulunan mektuplar yüzünden kocasının düelloyla sevgilisini öldürüp onu terk etmesi', ['Kocasının iflas etmesi', 'Kızının ölümü', 'Bir hastalığa yakalanması'], 'Genç yaşta evlendirilen Effi\'nin eski bir ilişkisi ortaya çıkar; kocası Instetten toplumsal onur kuralları gereği düello yapar. Roman Prusya ahlak anlayışını eleştirir.'),
  ('Theodor Storm\'un \'Atlı Hayalet\' (Der Schimmelreiter) novellasında Hauke Haien\'ın mücadelesi neyle ilgilidir?', 'Kuzey Denizi kıyısında set yaptırarak köyü selden korumak', ['Bir hazine avına çıkıp korsanlardan altın sandığını geri almak', 'Bir yelkenli yarışı', 'Bir madeni açmak'], 'Hauke, köylülerin direnişine rağmen yeni bir set yaptırır; sonunda sel hem onu hem ailesini yutar. Novella insanın doğaya meydan okuyuşunu işler.'),
  ('\'Şiirsel Gerçekçilik\' (Poetischer Realismus) anlayışı gerçeği nasıl ele alır?', 'Gerçeği süzgeçten geçirerek, yumuşatıp şiirsel bir dille sunar', ['Olduğu gibi acımasızca belgeler', 'Tümüyle fantastik bir dünya kurar', 'Sadece siyasi manifesto yazar'], 'Alman gerçekçileri toplumsal çirkinliği doğrudan değil, mizah ve şiirsel bir mesafeyle aktardı; Fransız gerçekçilerinden bu yönüyle ayrıldılar.'),
  ('Annette von Droste-Hülshoff\'un \'Yahudi Kayını\' (Die Judenbuche) hangi türde ve konuda bir yapıttır?', 'Kırsalda suç ve vicdan azabı novellası', ['Orta Çağ\'daki bir savaşı anlatan tarihî destan', 'Bir şiirsel aşk romanı', 'Bir çocuk masalı'], 'Friedrich Mergel\'in cinayeti ve yıllar sonra kayın ağacında asılı bulunuşu, günah ve kader temalarını işler.'),
  ('Fontane\'nin \'Effi Briest\' romanında Effi\'nin kocası Instetten\'ın tutumunu en iyi tanımlayan kavram hangisidir?', 'Toplumsal onur kurallarına katı itaat', ['Kıskançlık yüzünden aklını yitiren bir kocanın deliliği', 'Merhamet', 'Dinî hoşgörü'], 'Instetten, aslında sevgisi kalmadığı hâlde \'toplumun beklentisi\' gereği düello yapar; roman, bireyi ezen toplum kurallarını eleştirir.'),
  ('Gerhart Hauptmann\'ın doğalcı oyunlarında dil nasıldır?', 'Karakterlerin konuştuğu lehçeyi yansıtan yalın ve gündelik bir dil', ['Süslü ve ölçülü bir şiir dili', 'Yapay ve kitabi bir dil', 'Latince'], 'Doğalcı tiyatroda gerçekçilik için karakterler kendi sosyal konumlarına uygun lehçeyle konuşur; bu, sahnede toplumsal gerçekliği artırır.'),
  ('Arno Holz\'un savunduğu \'saniye üslubu\' (Sekundenstil) neye dayanır?', 'Gerçekliği ayrıntıyı atmadan anında kaydetmeye', ['Rüyaları ve bilinçaltı görüntüleri şiirsel biçimde anlatmaya', 'Dizeleri sayarak yazmaya', 'Mitolojiyi yeniden yazmaya'], 'Holz ve Schlaf, \'Papa Hamlet\' gibi eserlerde, konuşma ve davranış ayrıntılarını bilimsel hassasiyetle aktarmaya çalıştı.'),
  ('Frank Wedekind\'in \'Bahar Uyanışı\' oyunu hangi yüzünden sansüre uğramıştır?', 'Gençlerin cinselliğini ve baskıcı eğitimi açıkça işlemesi', ['Krala ve saray çevresine açıkça hakaret içermesi nedeniyle', 'Dinî ibadetlere saygısızlık', 'Savaş propagandası'], 'Oyun, Alman okul ve aile düzeninin gençlerin cinsel bilinçlenmesini bastırışını eleştirir ve intiharla sonuçlanan trajedileri gösterir.'),
  ('Rilke\'nin \'Malte Laurids Brigge\'nin Notları\' romanı hangi biçimdedir?', 'Parçalı, günlük niteliğinde not defteri', ['Klasik biçimli ve kronolojik bir tarihî roman', 'Mektup romanı', 'Sahne oyunu'], 'Paris\'te yoksulluk ve ölüm düşünceleriyle boğuşan genç şairin parçalı notları, modernist romanın öncülerindendir.'),
  ('Rilke\'nin \'Orpheus\'a Soneler\' koleksiyonu hangi temaları işler?', 'Dönüşüm, ölüm ve şarkının kalıcılığını', ['Savaş ve yıkımı', 'Siyasi hiciv', 'Ticari hayatı'], 'Rilke, 1922\'de çok kısa sürede yazdığı sonelerde Orpheus mitini kullanarak şiir ve ölümsüzlük üzerine düşünür.'),
  ('Ekspresyonizm edebiyatta neyi ön plana çıkarır?', 'Dış gerçekliğin yansıtılmasından çok iç dünyanın çığlığını', ['Dış dünyanın nesnel ve ayrıntılı betimlemesini yapmayı ve belgelemeyi', 'Mizahi taklidi', 'Antik formları'], 'Ekspresyonistler, bireyin korku, öfke ve umut gibi güçlü içsel duygularını çarpıtılmış biçimlerle dışa vurur.'),
  ('Kurt Pinthus\'un 1919\'da hazırladığı ekspresyonist şiir antolojisinin adı nedir?', 'İnsanlığın Alacakaranlığı', ['Dünyanın Şafağı: Yeni İnsanlığın Gün Doğumu Şiirleri', 'Bahar Çiçekleri', 'Gece Marşı'], 'Antoloji, Heym, Trakl, Benn gibi şairleri bir araya getirip savaş öncesi ve sonrası ekspresyonist şiirin panoramasını verdi.'),
  ('Gottfried Benn\'in \'Morgue\' şiirlerinde tıbbi gerçeklikle ne yapılmıştır?', 'Ölümü ve çürümeyi soğuk klinik gözle şiire taşımak', ['Hekimlere ve hastanelere duyulan övgü ve minneti dile getirmek', 'Bilimsel icatları anlatmak', 'Savaşı kutlamak'], 'Hekim şair Benn, ölü bedenleri şiirde nesnel biçimde betimleyerek romantik şiir anlayışına meydan okudu.'),
  ('Alfred Döblin\'in \'Berlin Alexanderplatz\' romanında Franz Biberkopf\'un çabası nedir?', 'Hapisten çıktıktan sonra namuslu yaşamaya çalışması', ['Bir hazine bulup zengin olarak eski kasabasına dönmek', 'Bir politikacı olmak', 'Bir kasabayı yönetmek'], 'Biberkopf, Berlin\'in alt dünyasında doğruluk arayışında defalarca düşer; roman montaj tekniği ve gazete parçalarıyla büyük şehir deneyimini yansıtır.'),
  ('Georg Kaiser\'in \'Gaz\' oyunu hangi toplumsal sorunu işler?', 'Sanayileşmenin insanı ve toplumu yabancılaştırması', ['Savaş sonrası yoksulluk, işsizlik ve konut sıkıntısı', 'Dinî çatışma', 'Köylü ayaklanması'], 'Oyun, bir gaz fabrikasının patlaması etrafında teknik ilerleme ile insan değerinin çatışmasını ekspresyonist biçimde işler.'),
  ('Else Lasker-Schüler\'in şiirlerinin ayırıcı özelliği nedir?', 'Doğu masalı imgeleri ve özgün bir duygusal dil', ['Yalın, doğrudan ve siyasal bildirilere yakın bir dil', 'Bilimsel terminoloji', 'Gündelik gazete dili'], 'Berlinli Yahudi şair Lasker-Schüler, hayal gücünü ve dinî imgelerini birleştiren özgün bir şiirsel dünya yarattı.'),
  ('Thomas Mann\'ın \'Tonio Kröger\' novellasında kahramanın yaşadığı temel çatışma nedir?', 'Sanatçı kimliği ile sıradan yaşam özlemi arasındaki gerilim', ['İki kardeşin miras yüzünden yıllarca süren mahkeme kavgası ve düşmanlığı', 'Bir aşkın siyasi engeli', 'Savaş travması'], 'Tonio, \'sağlıklı\' burjuva yaşamına özlem duyan ama sanatçı olmanın ayrı kıldığı bir karakterdir; bu tema Mann\'ın birçok eserinde yinelenir.'),
  ('Mann\'ın \'Mario ve Büyücü\' öyküsü hangi siyasi gerçeği sembolik olarak işler?', 'İtalyan faşizminde iradenin büyüyle ele geçirilmesi', ['Alman savaş sanayisinin işçileri sömürmesi ve yıkımı', 'Rusya\'daki devrim', 'Amerikan Buhranı'], 'İtalya\'da tatilde karşılaşılan hipnozcu, kitleleri iradesizleştiren faşizmin bir alegorisi olarak okunur.'),
  ('Mann\'ın 1929\'da Nobel almasında en belirleyici olarak hangi yapıtı gösterilmiştir?', 'Buddenbrooklar', ['Büyülü Dağ romanı', 'Doktor Faustus', 'Tonio Kröger'], 'Nobel jürisi, özellikle Buddenbrooklar\'ı anarak ödülü verdi; \'Büyülü Dağ\' ise bu gerekçede açıkça anılmadı.'),
  ('Franz Kafka\'nın \'Ceza Sömürgesi\'nde idam mahkûmunun cezası nasıl gerçekleşir?', 'Suçun adı bir makinece vücudunun üzerine kazınır', ['Zehir içirilip hücrede yavaş yavaş öldürülerek infaz edilir', 'Yakılarak', 'Dar ağacıyla'], 'Makine, yargılanan kişiye hakkında hüküm verilmeden cezasını bedenine yazar; öykü adaletin ve otoritenin şiddetini işler.'),
  ('Kafka\'nın \'Amerika\' romanında kahramanın yolculuğu neyi gösterir?', 'Karl Rossmann\'ın yeni dünyada yabancılaşması', ['Zenginleşip yeni dünyada mutlu bir yaşama kavuşma', 'Politik yükseliş', 'Askerî kahramanlık'], 'Roman, ailesi tarafından Amerika\'ya gönderilen genç göçmenin başarısız uyum çabalarını ve toplumsal baskıyı anlatır.'),
  ('Kafka\'nın \'Babaya Mektup\' metninde yazarın yakındığı şey nedir?', 'Babasının baskıcı tutumunun çocukluğunda yarattığı korku ve güvensizlik', ['Babasının yoksulluğu', 'Babasının hastalığı', 'Babasının göçü'], 'Kafka bu uzun mektubu hiçbir zaman babasına ulaştırmadı; metin yazarın aile içi ilişkisinin kaygılarını gösterir.'),
  ('Kafka\'nın \'Dönüşüm\' öyküsünde Gregor\'un ailesinin ona tutumu zamanla nasıl değişir?', 'Önce şaşkınlık ve acıma, sonra yük hissi', ['Önce nefret, sonra büyük bir şefkat ve sevgiyle', 'Her zaman şefkatle', 'Hiç ilgilenmeyerek'], 'Gregor ekonomik olarak işe yaramaz hale gelince ailesi onu bir yük görür; ölümü sonrası rahatlarlar. Öykü yabancılaşmayı ve aile ilişkisini sorgular.'),
  ('Kafka\'nın \'Dava\' romanında Josef K.\'nın tutuklanışının ilginç yanı nedir?', 'Tutuklandığı sabah suçlamanın ne olduğu kendisine hiç söylenmez', ['Çok sert işkence görmesi', 'Hapishaneden kaçması', 'Hâkimi tanıması'], 'Josef K. özgür bırakılsa da yargılama süreci içinde yıpranır; belirsizlik, bürokratik yargı ve suçluluk romanın temel temalarıdır.'),
  ('Kafka\'nın eserlerinde sıkça görülen anlatı özelliği hangisidir?', 'Gerçekçi dille anlatılan absürt ve kâbusvari durumlar', ['Süslü, şiirsel ve ağdalı bir anlatım dili ve duygu yüklü sözcükler', 'Mizahi fabl', 'Epik betimleme'], 'Kafka, olağanüstü olayları ciddi ve ayrıntılı bir dille sunarak okuru huzursuz eder.'),
  ('Hermann Hesse\'nin \'Narziss ile Goldmund\' romanında iki arkadaşın karşıt yaşam biçimleri nedir?', 'Narziss düşünce ve manastırı, Goldmund duyusal sanatçı yaşamı temsil eder', ['Biri savaşçı bir asker, diğeri zengin bir tüccar olarak aynı kadını sever ve çatışır', 'Biri doktor, diğeri avukat', 'Biri çiftçi, diğeri denizci'], 'Roman, akıl ile duygu, ruh ile beden arasındaki ikiliği iki dostun yolları üzerinden anlatır.'),
  ('Hesse\'nin \'Demian\' romanında Emil Sinclair\'in dönüşümüne yol açan karakter kimdir?', 'Max Demian', ['Pistorius', 'Franz Kromer', 'Narziss'], 'Demian, Sinclair\'e iyi ile kötü ikiliğini aşmayı ve kendi yolunu bulmayı öğretir; roman, Jung\'un etkisinde bir bireyleşme anlatısıdır.'),
  ('Remarque\'ın \'Üç Arkadaş\' romanında arkadaşlar nasıl bir toplumsal ortamda yaşar?', 'Savaş sonrası Almanya\'sında ekonomik kriz ve yoksulluk içinde', ['Amerikan Batı sınırında', 'Orta Çağ Avrupa\'sında', 'Fransız Devrimi sırasında'], 'Üç eski asker, tamirhane işleten arkadaşlıkları ve Pat\'in hastalığı çevresinde Weimar Cumhuriyeti\'nin son yıllarının atmosferini yansıtır.'),
  ('Brecht\'in \'Üç Kuruşluk Opera\' eserinde Mackie Messer karakteri neyi simgeler?', 'Burjuva toplumundaki soyguncu ile işadamının benzerliğini', ['Bir kahraman şövalyeyi', 'Bir halk önderini', 'Bir melek elçisini'], 'Haydut Mackie Messer, burjuva düzeninin yasal hırsızlarına benzetilir; Kurt Weill\'in müziğiyle oyun kapitalizm eleştirisi sunar.'),
  ('Brecht\'in \'Galilei\'nin Yaşamı\' oyununda Galilei\'nin engizisyon karşısında geri adım atması neyi tartıştırır?', 'Bilim insanının sorumluluğu ve doğrulukla yüzleşmesini', ['Din bilginlerinin bilim insanlarından her zaman üstün olduğunu', 'Sanatın önemini', 'Savaş taktiklerini'], 'Galilei yeryüzünün döndüğü görüşünden vazgeçer, ama sonra kendini bilim insanı olarak sorgular; oyun bilginin toplumsal sorumluluğunu işler.'),
  ('Brecht\'in \'Szechwan\'ın İyi İnsanı\' oyunundaki Shen Te\'nin Shui Ta kılığına girmesinin nedeni nedir?', 'İyi kalmanın acımasız dünyada imkânsız olduğunu göstermek', ['Askerlikten kaçıp savaş yıllarını gizlice geçirmek ve saklanmak', 'Sahnede eğlence yaratmak', 'Borçlarından kurtulmak'], 'Shen Te, iyi yürekli kalarak ayakta duramayınca amcası Shui Ta kılığında sert davranır; oyun, kapitalist düzende iyiliğin imkânsızlığını gösterir.'),
  ('Brecht\'in 1949\'da Doğu Berlin\'de Helene Weigel ile kurduğu tiyatro topluluğu hangisidir?', 'Berliner Ensemble', ['Burgtheater topluluğu', 'Schaubühne', 'Globe'], 'Berliner Ensemble, Brecht\'in epik tiyatro anlayışını uygulayan ve onun oyunlarını sahneleyen topluluktur.'),
  ('Dürrenmatt\'ın \'Fizikçiler\' oyununun geçtiği yer neresidir ve ana düşüncesi nedir?', 'Bir akıl hastanesi; bilimin sorumsuz kullanımı tehlikesi', ['Bir üniversite; öğrencilerin sınav ve not sistemine tepkileri', 'Bir ordu; savaş taktikleri', 'Bir saray; kral tutkusu'], 'Fizikçi Möbius deliliği oynayarak keşiflerini gizler; ama sonunda dünyaya yararsız çıkar. Oyun, bilimin etik sorumluluğunu tartışır.'),
  ('Max Frisch\'in \'Biedermann ve Kundakçılar\' oyunundaki Biedermann\'ın hatası nedir?', 'Evine yerleşen kundakçılara karşı ürkek ve uyumcu davranması', ['Yangını kendisinin çıkarması', 'Ev satmayı reddetmesi', 'Polise başvurması'], 'Oyun, kötülüğe göz yuman ve onu fark etmeyen burjuvanın zayıflığını, faşizmin yükselişine alegori olarak işler.'),
  ('Savaş sonrası Alman edebiyatında \'Trümmerliteratur\' (enkaz edebiyatı) nedir?', 'Savaşın yıkımını yalın dille anlatan 1945 sonrası edebiyat', ['Antik tragedyaların yeniden yazılması ve sahnelenmesi akımı', 'Orta Çağ efsanelerinin çevirisi', 'Bilimkurgu'], 'Enkaz edebiyatı, Alman şehirlerinin yıkıntıları ve insanların maddi-manevi çöküşü üzerine sade ve sert bir anlatımla yazıldı.'),
  ('Wolfgang Borchert\'in \'Kapının Önünde\' oyununda Beckmann\'ın durumu nedir?', 'Savaştan dönen, evine ve topluma uyum sağlayamayan asker', ['Savaşa giden genç', 'Zafer kazanan komutan', 'Yeni evli çift'], 'Beckmann, savaştan sonra eve dönse de kimse onu kabul etmez; oyun kayıp kuşağın umutsuzluğunu anlatır.'),
  ('\'Grup 47\' (Gruppe 47) nedir?', 'Savaş sonrası yazarların eserlerini okuyup eleştirdiği topluluk', ['Savaş sonrası kurulan ve seçimlere katılan bir siyasi parti hareketi', 'Bir yayınevi', 'Bir tiyatro topluluğu'], 'Hans Werner Richter\'in 1947\'de kurduğu grup, Böll, Grass, Bachmann gibi yazarları bir araya getirip Alman edebiyatının yeniden doğuşuna katkı sağladı.'),
  ('Ingeborg Bachmann\'ın şiir ve düzyazılarının ortak teması nedir?', 'Savaş sonrası yalnızlık, dil ve kadının konumu', ['Köylü yaşamının güzellikleri ve kırsal doğa betimlemesi', 'Kahramanlık destanı', 'Orta Çağ şövalye serüvenleri'], 'Avusturyalı Bachmann, dilin sınırları, şiddet ve kadın deneyimi üzerine yoğun, felsefi bir yazım geliştirdi.'),
  ('Siegfried Lenz\'in \'Alman Dersi\' romanında Siggi Jepsen\'in cezası nasıl bir görevdir?', 'Görev zevki konulu bir kompozisyon yazması', ['Uzun bir şiiri ezberleyip tüm sınıfa okuması', 'Tarih sınavı vermesi', 'Resim yapması'], 'Siggi, bir ıslahevinde babasının Nazi döneminde bir ressama uyguladığı yasak resim denetiminin anısını yazarak sorgular.'),
  ('Elfriede Jelinek\'in \'Piyanist\' romanı hangi temayı işler?', 'Baskıcı anne ile kız ilişkisi ve bastırılmış arzular', ['Küçük bir şehrin tarihi ve yöneticilerinin siyasi öyküsü', 'Savaş kahramanlığı', 'Sanayi sendikaları'], 'Piyano öğretmeni Erika Kohut\'un annesinin egemenliğindeki yaşamı ve genç bir öğrenciyle ilişkisi, iktidar ve şiddet temalarıyla anlatılır.'),
  ('Herta Müller\'in yazarlığı hangi toplumsal koşulla sıkı biçimde bağlıdır?', 'Romanya\'daki Alman azınlık kökeni ve rejim baskısı', ['Fransa\'da sürgün yaşayıp orada yayımlanan eserler vermesi', 'İngiliz sömürgeciliği', 'Rus Devrimi'], 'Müller, Banat\'ta Alman azınlığın içinde büyüdü; rejimin gizli polisi tarafından izlendi. 2009 Nobel\'i aldı.'),
  ('Daniel Kehlmann\'ın \'Dünyanın Ölçülmesi\' romanında hangi iki bilim insanı karşılaştırılır?', 'Gauss ve Alexander von Humboldt', ['Einstein ve Planck', 'Kepler ve Newton', 'Freud ve Jung'], 'Roman, doğayı keşif gezileriyle ölçen Humboldt ile evinden çıkmadan matematiği geliştiren Gauss\'u mizahi bir dille karşılaştırır.'),
  ('W. G. Sebald\'ın romanlarında sık görülen biçim özelliği nedir?', 'Metinle fotoğraf ve belgesel öğelerin kullanılması', ['Uzun şiirlerle düzyazının dönüşümlü olarak kullanılması', 'Sahne yönergeleri', 'Mektuplar'], 'Sebald, anlatı ve fotoğrafı birleştirerek hafıza, kayıp ve Holokost\'u işler; \'Austerlitz\' bu tarzın bir örneğidir.'),
  ('Günter Wallraff\'ın \'En Dipte\' kitabı ne tür bir yöntemle yazılmıştır?', 'Göçmen işçi kılığında çalışıp gözlemlerini aktarması', ['Devlet arşivlerinde yıllarca belge araştırması yapılması', 'Hayal ürünü anlatı', 'Mektup derlemesi'], 'Wallraff, Türk işçisi \'Ali\' kimliğiyle Almanya\'da çalıştı ve ayrımcılığı belgeledi; kitap büyük toplumsal tartışma yarattı.'),
  ('Emine Sevgi Özdamar\'ın 1991\'de Ingeborg Bachmann Ödülü\'nü kazandığı eser hangisidir?', 'Hayat Bir Kervansaray, İki Kapısı Var', ['Anneannemin Evi ve Çocukluğum', 'Karagöz Berlin\'de', 'Gece ve Gündüz'], 'Almanca yazan Özdamar, Türkiye\'den Almanya\'ya göç deneyimini anlatan eserleriyle Alman edebiyatında ses getirdi; ödülü bir bölümüyle aldı.'),
  ('Alman edebiyatının \'Wende\' (dönüş) sonrası edebiyatı hangi olaya dayanır?', '1989\'da Duvar\'ın yıkılması ve Almanya\'nın birleşmesi', ['1933\'te Nazilerin iktidara gelmesi ve diktatörlüğün kurulması', '1945\'te savaşın bitişi', '1871\'de Alman birliği'], 'Birleşmeyle birlikte Doğu ve Batı yazarları kimlik, hafıza ve Stasi geçmişi gibi konuları yeni bir açıyla işledi.'),
  ('Alman edebiyatının dönemleri kronolojik olarak hangi seçenekteki gibi sıralanır?', 'Aydınlanma, Sturm und Drang, Klasisizm, Romantizm', ['Romantizm, Aydınlanma, Klasisizm, Sturm und Drang dönemleri', 'Klasisizm, Romantizm, Aydınlanma, Sturm und Drang', 'Sturm und Drang, Romantizm, Aydınlanma, Klasisizm'], 'Dönemler 18. yüzyıl ortasından itibaren Aydınlanma, Fırtına ve Coşku (1770\'ler), Weimar klasisizmi ve sonra Romantizm biçiminde ilerler.'),
  ('Thomas Bernhard\'ın romanlarında karakterlerin konuşma biçimi nasıldır?', 'Uzun, tekrarlı ve kızgın monologlarla', ['Kısa, şiirsel ve çok ölçülü cümlelerle', 'Resmî ve ölçülü', 'Çocuksu ve neşeli'], 'Bernhard, \'Yok Etme\' gibi eserlerinde Avusturya toplumunu ve kültürünü eleştiren uzun, döngüsel cümleler kurar.'),
  ('Dos Passos\'un \'U.S.A.\' üçlemesinde kullandığı \'Kamera Gözü\' bölümleri neyi sağlar?', 'Anlatıya anlık, belgesel nitelikli bir bakış katar', ['Kahramanın rüyalarını ve bilinçaltını şiirsel biçimde aktarır', 'Şiirli ağıtlar ekler', 'Yazarın otobiyografisini anlatır'], 'Üçlemede \'Kamera Gözü\', \'Haber Filmi\' ve kısa biyografiler, Amerika\'nın toplumsal bir panoramasını sunar.'),
  ('Poe\'nun \'Ligeia\' öyküsünde anlatıcının yeni karısı Rowena\'nın başına gelen olayın doruk noktası nedir?', 'Rowena\'nın cesedinin ölü Ligeia olarak canlanması', ['Rowena\'nın evden kaçıp başka bir ülkede yeni hayat kurması', 'Rowena\'nın zengin olması', 'Rowena\'nın evlenmemesi'], 'Anlatıcının ilk karısı Ligeia\'nın iradesiyle bedeni yeniden yaşama döndürdüğü ima edilir; öykü, ölümü yenen irade temasını işler.'),
  ('Ursula Le Guin\'in \'Karanlığın Sol Eli\' romanı hangi toplumsal temayı bilimkurguyla işler?', 'Cinsiyetin belirsizliği ve rollerin sorgulanması', ['Uzay yarışı ve iki süper güç arasındaki silahlanma rekabeti', 'İklim değişikliği', 'Yapay zekâ'], 'Gethen gezegeninde yaşayanlar belli dönemlerde cinsiyet kazanır; roman toplumsal cinsiyetin kurgusallığını araştırır.'),
  ('Frank Herbert\'in \'Dune\' romanında \'baharat\' (spice) neyi simgeler?', 'Gezegen ekonomisini ve iktidar mücadelesini besleyen değerli kaynak', ['Bir yemek türünü', 'Bir din adamını', 'Bir silahı'], 'Arrakis\'te bulunan melanj, uzay yolculuğu ve ömür uzatma için gereklidir; roman, kaynak, din ve ekolojiyi birleştirir.'),
  ('Claude McKay\'in \'Eğer Ölmemiz Gerekiyorsa\' şiiri hangi duyguyu yansıtır?', 'Irkçı şiddet karşısında onurlu direniş çağrısı', ['Doğa sevgisi ve kırsal yaşamın verdiği derin huzur', 'Dinî teslimiyet', 'Savaş yorgunluğu'], '1919 ırkçı şiddet olaylarından sonra yazılan sone, ölümle karşı karşıya kalındığında bile onurla direnilmesini söyler.'),
  ('Neruda\'nın \'Yeryüzünde Konut\' kitabının genel havası nasıldır?', 'Yalnızlık ve varoluşsal sıkıntı barındıran karamsar', ['Neşeli, coşkulu ve iyimser bir şölen havası taşıyan, umut dolu', 'Askerî ve kahramanlık dolu', 'Dinî ve vecd yüklü'], 'Şairin Doğu\'da konsolosluk yaptığı yıllarda yazılan şiirler, gerçeküstücü imgelerle yabancılaşma duygusunu aktarır.'),
  ('Octavio Paz\'ın \'Güneş Taşı\' şiirinin yapısındaki özellik nedir?', 'Aztek takvimi gibi döngüsel yapıda olması', ['Mektup biçiminde yazılıp sevgiliye gönderilmesi', 'Tek bir kafiyeyle yazılması', 'Düz yazı olması'], '584 dizelik şiir, Venüs döngüsüne gönderme yapar ve sonsuz dönüşü simgeler.'),
  ('César Vallejo\'nun \'İspanya, Şu Kadehi Benden Uzaklaştır\' kitabı hangi olayla ilgilidir?', 'İspanya İç Savaşı', ['Meksika Devrimi', 'Bağımsızlık Savaşı', 'Küba Krizi'], 'Vallejo, savaş sırasında İspanya Cumhuriyetçilerini destekleyen şiirler yazdı; kitap ölümünden sonra yayımlandı.'),
  ('Mario Benedetti\'nin \'Ateşkes\' romanı hangi biçimde yazılmıştır?', 'Bir büro memurunun günlüğü', ['Mektuplar', 'Mahkeme tutanağı', 'Tiyatro metni'], 'Uruguaylı Benedetti, emeklilik arifesindeki Martín Santomé\'nin günlüğü aracılığıyla kentli orta sınıfı ve yalnızlığı anlatır.'),
  ('Alvaro Mutis\'in romanlarında sıkça karşılaşılan kahraman kimdir?', 'Gezgin ve karamsar denizci Maqroll el Gaviero', ['Albay Aureliano Buendía\'nın küçük oğlu ve hazine avcısı', 'Kaptan Ahab', 'Don Segundo'], 'Mutis\'in Maqroll\'u yaşamı boyunca dolaşan, kayıpları ve yalnızlığı simgeleyen bir figürdür.'),
  ('José María Arguedas\'ın romanlarında temel çatışma nedir?', 'And kültürü ile Batı kültürü gerilimi', ['Denizcilik ve liman işçiliği sorunları', 'Büyük şehir hayatı', 'Endüstri grevleri'], 'Arguedas, Quechua kültüründe yetişmiş bir yazar olarak \'Derin Nehirler\' gibi eserlerinde yerli ve mestizo kimliğin sorunlarını işledi.'),
  ('Gioconda Belli\'nin \'Yeryüzündeki Kadın\' romanı nasıl bir kadın portresi çizer?', 'Siyasal mücadelede yer alıp bedenini keşfeden kadın', ['Sarayda yaşayıp taht kavgasına karışan genç ve hırslı prenses', 'Çiftlikte çalışan hizmetçi', 'Denizci'], 'Nikaragualı Belli, Sandinista deneyimini yaşamış bir yazar; romanında kadın özgürlüğü ve siyasal katılım iç içe verilir.'),
  ('Silvina Ocampo\'nun öykülerini özgün kılan nedir?', 'Gündelik olanda tekinsiz olanı ortaya çıkarması', ['Destansı savaş anlatımı ve askerî kahramanlık övgüsü', 'Siyasi hiciv', 'Çocuk eğitimi'], 'Arjantinli Ocampo, çocukluk, hizmetçiler ve ev içi mekânlarda gizlenen tekinsizliği ince bir ironiyle anlatır.'),
  ('José de Alencar\'ın \'Guarani\' romanı hangi akımın Brezilya\'daki örneğidir?', 'Romantizmin \'yerlici\' (indianist) çizgisi', ['Doğalcılık ve bilimsel gözlem çizgisinin bir örneği', 'Sürrealizm', 'Minimalizm'], 'Alencar, Brezilya\'nın ulusal edebiyatını yaratma çabasıyla yerli kahramanı idealleştiren romanlar yazdı.'),
  ('Jorge Amado\'nun \'Kaptanlar\' romanında \'Kumsal Kaptanları\' kimlerdir?', 'Salvador\'un kumsallarında yaşayan başıboş çocuklar', ['Gemi kaptanları', 'Madenci grevcileri', 'Çiftlik sahipleri'], 'Roman, Bahia\'da sokakta yaşayan çocukların dayanışmasını ve toplumsal adaletsizliği anlatır.'),
  ('Latin Amerika edebiyatında \'indigenismo\' (yerlicilik) neyi hedefler?', 'Yerli halkın durumunu ve kültürünü edebiyatta görünür kılmayı', ['Avrupa\'dan gelen göçmenleri kıtaya yerleşmeye teşvik edip övmeyi', 'Köleliği sürdürmeyi', 'Latince yazmayı'], 'Yerlicilik, Ciro Alegría ve Arguedas gibi yazarlarla yerli köylülerin yaşamını ve haklarını merkeze alan bir akımdır.'),
  ('Goethe\'nin \'Prometheus\' şiirinde Tanrı\'ya karşı tutum nasıldır?', 'İnsanın tanrılara boyun eğmeyip kendine güvenmesi', ['Tanrılara koşulsuz teslimiyet ve onların iradesine boyun eğiş', 'Dinî ibadet çağrısı', 'Tanrılara övgü'], 'Prometheus, Zeus\'a meydan okur; şiir Sturm und Drang\'ın dahi ve başkaldıran bireyini yücelten bir manifestodur.'),
  ('Goethe\'nin \'Weltliteratur\' (dünya edebiyatı) kavramı neyi önerir?', 'Ulusal edebiyatların birbirinden etkilenip ortak bir dünya edebiyatı oluşturmasını', ['Her ulusun yalnızca kendi dilinde yazmasını', 'Edebiyatın yalnızca Avrupa\'ya ait olmasını', 'Çeviri yapılmamasını'], 'Goethe, Doğu ve Batı edebiyatını okuyarak ulusal sınırları aşan bir edebiyat anlayışını savundu; bu kavram bugün de kullanılır.'),
  ('Goethe\'nin \'Hermann ile Dorothea\' epik şiiri hangi dönemde geçer?', 'Fransız Devrimi\'nin yarattığı mülteci akını yılları', ['Haçlı seferleri sırasında bir şövalyenin Kudüs yolculuğu', 'Otuz Yıl Savaşları', 'Rönesans'], 'Küçük kasabada bir çiftçi oğlu ile mülteci kız arasındaki aşk, devrim ve savaşın gölgesinde anlatılır.'),
  ('Goethe\'nin \'Renk Öğretisi\' yapıtı hangi alandaki iddiasıyla tartışma yaratmıştır?', 'Newton\'un ışık kuramına karşı çıkması', ['Darwin\'in evrim kuramına karşı çıkması', 'Atom teorisini savunması', 'Sanayi devrimini eleştirmesi'], 'Goethe, renklerin yalnızca fiziksel değil, algısal ve duygusal olduğunu savundu; bilim çevreleri Newton\'a bağlı kaldı.'),
  ('Goethe\'nin \'Werther\'in Acıları\' romanının epistolar (mektup) biçimi okura ne sağlar?', 'Kahramanın iç dünyasına doğrudan ve duygusal bir yakınlık', ['Tarihî belge niteliği', 'Mizahi bir mesafe', 'Bilimsel nesnellik'], 'Mektuplar Werther\'in duygularını anında yansıtır; okur olayları yalnızca onun gözünden izler.'),
  ('Goethe\'nin \'Faust\' birinci bölümündeki \'Walpurgis Gecesi\' sahnesi neyi gösterir?', 'Faust\'un cadılar ve şeytanlar âlemini görmesi', ['Şatoda verilen büyük bir saray şöleni ve baloları', 'Savaş meydanı', 'Bir okul dersi'], 'Faust, Gretchen\'i terk ettikten sonra Mephistopheles tarafından cadı şenliğine götürülür; sahne ahlaki çözülmeyi simgeler.'),
  ('Schiller\'in \'Wilhelm Tell\' oyununda halkı ayaklanmaya iten şey nedir?', 'Habsburg kâhyası Gessler\'in zorbalığı ve şapka dayatması', ['Kuraklık', 'Bir salgın hastalık', 'Bir din savaşı'], 'Gessler\'in bir direğe astırdığı şapkaya saygı gösterilmesini zorlaması, Tell\'in elmayı vurması ve ayaklanma zincirini başlatır.'),
  ('Moritz\'in \'Anton Reiser\' eseri hangi türün öncüsüdür?', 'Psikolojik roman', ['Polisiye roman türünün', 'Destan', 'Fantastik masal'], 'Moritz, Anton\'un çocukluğunu ve ruhsal acılarını gerçekçi biçimde anlatarak psikolojik romanın erken örneğini verdi.'),
  ('Bir öğretmen, \'sıradan insan gündelik koşullarda çöker\' temasını iki eserle göstermek istiyor. Hangi ikili en uygun örnektir?', 'Miller\'in \'Bir Satıcının Ölümü\' ile Fontane\'nin \'Effi Briest\'i', ['Cervantes\'in \'Don Kişot\'u ile Poe\'nun \'Kuzgun\'u', 'Whitman\'ın \'Çimen Yaprakları\' ile Neruda\'nın \'Canto General\' adlı destansı şiiri', 'Goethe\'nin \'Faust\'u ile Márquez\'in \'Yüzyıllık Yalnızlık\'ı'], 'Willy Loman ve Effi, toplumsal beklentilerin yıktığı sıradan insanlardır; diğer ikililerde epik ya da destansal kahramanlar vardır.'),
  ('Hem savaşın sıradan insana etkisini hem de savaşa karşı propagandaya tepkiyi anlatan iki roman seçilecektir. Hangi eşleşme doğrudur?', 'Remarque\'ın \'Batı Cephesinde Yeni Bir Şey Yok\'u ile Heller\'in \'Madde 22\'si', ['Whitman\'ın \'Kendimin Şarkısı\' ile Dickinson şiirleri', 'Cortázar\'ın \'Seksek\'i ile Borges\'in \'Alef\'i', 'Goethe\'nin \'Werther\'i ile Schiller\'in \'Haydutlar\'ı'], 'İki roman, savaş makinesine karşı bireyin savunmasızlığını ve savaş söyleminin ikiyüzlülüğünü gösterir.'),
  ('Bir lise öğrencisi, \'diktatörün portresini mizah ve abartıyla veren\' bir Latin Amerika romanı arıyor. Hangisini önerirsiniz?', 'García Márquez\'in \'Patriğin Sonbaharı\'', ['Gallegos\'un \'Doña Bárbara\' adlı bölgeci romanı', 'Quiroga\'nın \'Anakonda\'sı', 'Isaacs\'ın \'María\'sı'], 'Patriğin Sonbaharı bir diktatörün yalnızlığını ve kibrini abartılı, uzun cümlelerle gösterir.'),
  ('Poe ile Hawthorne arasındaki ortak yön nedir?', 'İkisinde de karanlık ve suçluluk temaları ağır basar', ['İkisinin de yalnızca şiir yazıp roman ve öyküye hiç yönelmemesi', 'İkisinin de siyasi kariyer yapması', 'İkisinin de sanayi romanları yazması'], 'Karanlık Romantizm olarak anılan bu çizgi, Transandantalistlerin iyimserliğine karşı insan ruhunun karanlık yanlarını işler.'),
  ('Hemingway\'in buzdağı ilkesi ile Raymond Carver\'ın minimalizminin benzerliği nedir?', 'İkisinde de anlam, söylenenlerin altında bırakılmış olarak okura bırakılır', ['İkisi de süslü anlatır', 'İkisi de açık ve açıklayıcıdır', 'İkisi de yalnızca şiir yazar'], 'Her iki yazar kısa ve yalın cümleler kullanır; asıl anlam yüzeyin altında, okurun çıkarımına bırakılır.'),
  ('Fitzgerald\'ın Gatsby\'si ile Dreiser\'in Clyde\'ı arasındaki ortak noktaya hangisi örnektir?', 'İkisi de yoksulluktan servet ve statü peşinde yıkılır', ['İkisi de ünlü birer savaş kahramanı ve madalyalı subaydır', 'İkisi de papazdır', 'İkisi de çiftçidir'], 'Amerikan Rüyası peşinde koşan iki kahraman da toplumsal sınıf engellerine ve ahlaki çöküşe çarpar.'),
  ('Faulkner\'ın \'Ses ve Öfke\'si ile Joyce\'un \'Ulysses\'i arasındaki teknik ortaklık nedir?', 'İkisinde de bilinç akışı tekniği kullanılır', ['İkisi de baştan sona manzum, şiir biçimindedir', 'İkisi de mektup romanıdır', 'İkisi de belgesel anlatıdır'], 'Her iki romanda da karakterlerin zihninden akan düşünceler doğrusal olmayan biçimde aktarılır.'),
  ('Alman klasisizmi ile Sturm und Drang arasındaki fark nedir?', 'Sturm und Drang coşkun ve başkaldıran; klasisizm ölçülü ve uyumlu bir üslup arar', ['Sturm und Drang ölçülü; klasisizm başkaldıran', 'İkisi de aynı anlayıştadır', 'İkisi de Orta Çağ geleneğini sürdürür'], 'Genç Goethe ve Schiller\'in coşkun dönemini, olgunluk dönemindeki denge ve form arayışı izledi.'),
  ('Amerikan Transandantalizmi ile Alman Romantizmi arasındaki bağlantı hangisidir?', 'İkisi de sezgiyi ve doğayla ruhsal birliği öne çıkarır', ['İkisi de fabrika emeğini ve sanayileşmenin ilerlemesini över', 'İkisi de yalnızca tiyatro yazar', 'İkisi de Orta Çağ kilisesini savunur'], 'Emerson, Alman idealizmi ve Romantizminden etkilendi; her iki akım da doğada ve bireyin içsel gücünde evrensel gerçeği arar.'),
  ('Emerson\'ın 1836 tarihli \'Doğa\' denemesi Transandantalizmin hangi iddiasını duyurur?', 'Doğanın ruhsal gerçeklerin görünür simgesi olduğunu', ['Doğanın yalnızca ekonomik kaynak olduğunu', 'İnsanın doğadan ayrıldığını', 'Doğanın tehlikeli olduğunu'], 'Emerson, doğayla doğrudan karşılaşmanın insana ilahi olanı gösterdiğini savundu; deneme akımın kurucu metni sayılır.'),
  ('Hemingway\'in \'Beyaz Fillere Benzeyen Tepeler\' öyküsünde çiftin konuşması neyi ima eder?', 'Kadının gebeliği ve alması gereken kararın gerilimi', ['Bir tren yolculuğunun planını ve bilet masraflarını tartışmayı', 'Bir iş görüşmesini', 'Bir miras tartışmasını'], 'Öyküde \'ameliyat\' sözcüğü açıkça geçmez; buzdağı ilkesi gereği asıl mesele konuşmanın altında bırakılır.'),
  ('Jack London\'ın \'Demir Ökçe\' romanı hangi türde yazılmıştır?', 'Distopik siyasi roman', ['Çocuklara yönelik macera kitabı', 'Aşk romanı', 'Dedektif romanı'], 'Roman, kapitalist oligarşinin işçi hareketini bastırdığı bir gelecek tasvir eder; London bu romanda sosyalist görüşlerini işler.'),
  ('1930\'larda Federal Writers\' Project hangi amaçla kurulmuştur?', 'Büyük Buhran\'da işsiz yazarlara iş sağlamak ve ülkenin kültürel mirasını belgelemek', ['Ordu için propaganda hazırlamak', 'Yabancı edebiyatı çevirmek', 'Okul müfredatı yazmak'], 'Programda köle anlatıları dahil çok sayıda yaşam öyküsü ve bölgesel rehber toplandı; Zora Neale Hurston ve Richard Wright gibi yazarlar da yer aldı.'),
  ('Yeni Eleştiri (New Criticism) akımı bir edebî metni nasıl inceler?', 'Yazarın hayatına bakmadan metnin biçim ve anlam ilişkisine odaklanarak', ['Yalnızca yazarın biyografisini ve kişisel hayatındaki olayları esas alarak', 'Tarihî koşullardan hareketle', 'Okurun duygusal tepkisinden hareketle'], 'Yeni Eleştirmenler, metni kapalı bir bütün olarak \'yakın okuma\' ile inceler; bu yaklaşım Amerikan üniversitelerinde yaygınlaştı.'),
  ('Edgar Allan Poe\'nun \'Kırmızı Ölümün Maskesi\' öyküsünde prens ve konukları neden felakete uğrar?', 'Veba salgınından kaçmak için saray köşkünde saklanırken ölümün kaçınılmazlığıyla karşılaşırlar', ['Savaş yüzünden', 'Deprem yüzünden', 'Taşkın yüzünden'], 'Maskeli baloda ortaya çıkan gizemli figür \'Kırmızı Ölüm\'dür; öykü ölümden kaçışın imkânsızlığını simgeler.'),
  ('Poe\'nun \'Çukur ve Sarkaç\' öyküsündeki Engizisyon işkencesinde kahramanı ne kurtarır?', 'Fareleri bağlarına kemirtmesi', ['Hapishane görevlisinin merhameti', 'Kaçışı', 'Büyü'], 'Kahraman, yağlı yiyeceklerle fareleri kendi iplerine çekerek bağlarını kemirtir; sonra duvarlar daralırken İspanya ordusu tarafından kurtarılır.'),
  ('Melville\'in \'Moby Dick\' romanındaki \'Beyaz Balina\'nın anlamı hakkında hangi yorum yaygındır?', 'Evrenin bilinemezliğini ve kötülüğün/doğanın karşı konulamaz gücünü simgeler', ['Bir kral portresi', 'Siyasi bir parti', 'Ticari bir marka'], 'Balina farklı yorumlara açıktır: doğa, tanrı, kader ya da kötülük; Ahab\'ın takıntısı insanın evren karşısındaki yenilgisini gösterir.'),
  ('Henry David Thoreau\'nun \'Walden\' kitabında zaman nasıl yapılandırılmıştır?', 'Bir yıllık mevsim döngüsü boyunca gözlemlerle', ['Bir savaşın günlük kayıtları ve cephe notları olarak', 'Haftalık raporlar halinde', 'Bir mahkeme duruşması biçiminde'], 'Kitap, iki yıl iki ayın deneyimini tek bir yıl içinde mevsimlere göre düzenler; doğanın döngüsü ruhsal yenilenmeyi simgeler.'),
  ('Borges\'in \'Alef\' öyküsündeki Aleph neye benzetilir?', 'Evrenin her noktasının aynı anda görüldüğü küçük bir nokta', ['Bir uzay gemisi', 'Bir hazine sandığı', 'Bir kitap'], 'Carlos Argentino\'nun bodrumunda bulunan Aleph, bütün evrenin bütün açılardan görülmesini sağlar.'),
  ('Borges\'in yapıtlarında kitaplık ve kütüphane imgeleri sık görülür. Bunun nedeni hangi biyografik gerçeğe bağlanır?', 'Kütüphane müdürlüğü ve çocukluktan okuma tutkusu', ['Mimarlık eğitimi alıp kütüphane binaları tasarlaması', 'Matbaacılık', 'Bibliyografya mesleği'], 'Borges babasının kütüphanesinde büyümüş ve sonradan Ulusal Kütüphane müdürü olmuştur; bu deneyim öykülerine yansır.'),
  ('Gabriela Mistral\'in çocuk ve öğretmenlik konusundaki çalışması edebiyat dışında hangi alana katkı yapmıştır?', 'Meksika ve Şili\'de eğitim reformlarına', ['Sanayi planlamasına', 'Tarımsal üretime', 'Askerî eğitime'], 'Mistral, öğretmenlikten gelen deneyimle Meksika\'da kırsal eğitim programlarına katkıda bulundu.'),
  ('Carlos Fuentes\'in \'Artemio Cruz\'un Ölümü\' romanında üç ayrı zamirle anlatılan bölümler (ben, sen, o) neyi gösterir?', 'Parçalanmış kimliğini ve çok katmanlı bilincini', ['Romanı üç ayrı yazarın birlikte kaleme aldığını', 'Üç farklı ülkeyi', 'Üç farklı mesleği'], 'Birinci, ikinci ve üçüncü kişi geçişleri, ölüm döşeğindeki Cruz\'un şimdi, geçmiş ve ahlaki yargılarını farklı seslerle aktarır.'),
  ('Vargas Llosa\'nın \'Kent ve Köpekler\' romanında Leoncio Prado askerî okulunun işlevi nedir?', 'Şiddet ve otorite sistemini gençlerin gözünden eleştirmek', ['Şiirsel doğa betimlemesi', 'Yerli halkın dinini anlatmak', 'Ticaret rehberi sunmak'], 'Okuldaki zorbalık ve erkeklik ritüelleri, Peru toplumundaki iktidar yapısının küçük bir modeli olarak gösterilir.'),
  ('Latin Amerika\'da \'costumbrismo\' akımı neyi betimler?', 'Yerel gelenek ve gündelik yaşam ayrıntılarını', ['Uzay yolculuklarını ve bilimkurgu serüvenlerini', 'Antik mitleri', 'Savaş stratejilerini'], 'Costumbrismo, 19. yüzyılda bölgesel örf ve adetleri betimleyen kısa anlatılara verilen addır.'),
  ('Latin Amerika\'da \'gaucho edebiyatı\' hangi coğrafyayla ilişkilidir?', 'Arjantin, Uruguay ve Güney Brezilya\'daki Pampa bozkırı', ['And dağları', 'Amazon ormanı', 'Karayip adaları'], 'Gaucho, pampalarda sığır güden at çobanıdır; Hernández ve Güiraldes bu kültürü edebiyata taşıdı.'),
  ('Latin Amerika \'sihirli gerçekçi\' romanlarında \'zaman\' nasıl ele alınır?', 'Doğrusal olmayan, döngüsel ve mitsel bir biçimde', ['Kesin kronolojik', 'Yalnızca saatle ölçülür', 'Bilimsel takvimle'], 'Macondo\'da zaman döngüseldir; olaylar tekrarlanır, geçmiş ve gelecek iç içe geçer.'),
  ('Klaus Mann\'ın \'Mephisto\' romanı hangi gerçek kişiyi çağrıştıran bir oyuncuyu eleştirir?', 'Nazi rejimiyle işbirliği yapan aktör Gründgens\'i', ['Nazi rejimine karşı çıkıp sürgüne giden Bertolt Brecht\'i', 'Max Reinhardt\'ı', 'Erwin Piscator\'u'], 'Roman, kariyeri için rejimin yanında yer alan bir tiyatrocunun ahlaki çöküşünü anlatır; Faust\'taki Mephisto göndermesi başlıkta vardır.'),
  ('Ödön von Horváth\'ın tiyatrosunda eleştirilen toplumsal kesim hangisidir?', 'Faşizme kayan küçük burjuvazi', ['Büyük toprak sahibi soylu aileler', 'Din adamları', 'Savaş komutanları'], 'Horváth, \'Viyana Ormanı\'nın Hikâyeleri\' gibi oyunlarında küçük burjuvanın ikiyüzlülüğünü ve kaba bayağılığını gösterir.'),
  ('Erich Kästner\'in \'Fabian\' romanı hangi dönemi anlatır?', 'Weimar\'ın son yıllarındaki Berlin\'i', ['Napolyon döneminin savaş ve istilalarını', 'Haçlı seferlerini', 'Roma imparatorluğunu'], 'Fabian, ahlak çöküşü içindeki Berlin\'de ideal arayan ama yönünü bulamayan bir gençtir; roman dönemin keskin bir tanığıdır.'),
  ('Kurt Tucholsky\'nin yazılarının başlıca özelliği nedir?', 'Siyasi hiciv ve savaş karşıtı gazetecilik', ['Aşk şiirleri', 'Tarih kitapları', 'Kutsal kitap yorumları'], 'Weimar döneminin gazeteci ve şairi Tucholsky, militarizmi ve yükselen faşizmi keskin bir mizahla eleştirdi.'),
  ('Rilke\'nin \'Genç Bir Şaire Mektuplar\' kitabında şairlik için verdiği temel öğüt nedir?', 'Yazmaktan başka çaresi olup olmadığını kendine sormak', ['Gazeteciliğe girip günlük kazancını artırmaya çalışmak', 'Eleştirmenlerin onayını almak', 'Çok yayın yapmak'], 'Rilke, genç şaire \'yazmaktan başka çaren yoksa\' yazması gerektiğini ve dış onaya bakmamasını söyler.'),
  ('Stefan Zweig\'in \'Satranç\' novellasında Dr. B.\'nin takıntısı nasıl gelişir?', 'Hapishanede bulduğu bir satranç kitabını ezberleyerek kendi kendine oynaması yüzünden', ['Satranç kulübünde çalışarak', 'Gemide dersler vererek', 'Bir yarışma kazanarak'], 'Gestapo tecridinde akli dengesini korumak için oynadığı oyun, onu bir tür bölünmeye götürür; novella tecrit ve zihin sağlığı üzerinedir.'),
  ('Alman edebiyatında \'Heimatliteratur\' (yurt edebiyatı) neyi öne çıkarır?', 'Kırsal yaşamı ve toprak bağlılığını', ['Büyük şehirlerin entelektüel ve sanatsal hayatını', 'Uzay yolculuğunu', 'Sınır ötesi göçü'], 'Bu akım, doğup büyüdüğü bölgenin geleneklerini ve doğasını yücelten romanlara verilen addır; Nazi döneminde bazı biçimleri propagandaya alet edildi.'),
  ('Alman edebiyatında \'Novelle\' türü nasıl tanımlanır?', 'Tek bir olağandışı olay etrafında yoğunlaşan kısa anlatı', ['Birçok kuşağın öyküsünü anlatan uzun ve çok ciltli bir destan', 'Tek perdelik oyun', 'Aforizma derlemesi'], 'Alman edebiyatında Goethe, Kleist, Storm ve Keller gibi yazarlar novelle türünün önemli örneklerini verdi.'),
  ('Fontane\'nin \'Stechlin\' romanında göl neyi simgeler?', 'Uzak olaylarla bağlantıyı ve değişimin habercisini', ['Soylu ailenin zenginliğini ve toprak servetinin gücünü', 'Savaş zaferini', 'Çocukluğu'], 'Stechlin Gölü uzak depremlerde kabarır; bu, eski düzenin çöküşü ve yeni dönemin yaklaşışını simgeler.'),
  ('Wilhelm Raabe\'nin \'Serçelerin Sokağı\' romanı hangi konuyu işler?', 'Küçük insanların ahlaki dayanışmasını', ['Savaşta gösterilen kahramanlığı ve vatan sevgisini', 'Saray entrikalarını', 'Gezgin gemiciliği'], 'Raabe, mizah ve hüzünle kasabanın yoksulluğunu ve insanlığı gösterir; gerçekçi dönemin önemli yazarlarındandır.'),
  ('Gerhart Hauptmann\'ın \'Dokumacılar\' oyununda ayaklanmanın nedeni nedir?', 'Yoksul dokumacıların fabrika sahiplerinin sömürüsüne karşı başkaldırması', ['Dinî baskı', 'Savaş vergisi', 'Kuraklık'], '1844 Silezya dokumacıları, düşük ücret ve açlık nedeniyle ayaklandı; oyun toplu acıyı bir kahramana indirgemeden gösterir.'),
  ('Hans Magnus Enzensberger\'in şiirlerinde baskın tutum nedir?', 'Siyasi ve toplumsal eleştiri ve ironi', ['Doğa övgüsü ve kırsal yaşamın huzurunun yüceltilmesi', 'Dinî vecd', 'Aşk romantizmi'], 'Enzensberger, savaş sonrası toplumun tüketim kültürünü ve siyasal çelişkilerini keskin ironiyle dile getirdi.'),
  ('\'Büyük Amerikan Romanı\' deyimi neyi anlatır?', 'Amerikan ulusunun yaşamını ve karakterini bütünüyle yansıtacağı varsayılan roman idealini', ['En uzun romanı', 'En çok satan kitabı', 'Ödül almış tüm romanları'], 'Deyim 19. yüzyıldan beri yazarların hedeflediği bütün ulusu kapsayan roman fikrini ifade eder; Moby Dick ve Gatsby sıkça örnek gösterilir.'),
  ('Whitman\'ın \'Çimen Yaprakları\' şiir kitabı ömrü boyunca ne şekilde gelişmiştir?', 'Yeni şiirler eklenerek birçok baskıda genişletilmiştir', ['Yalnızca tek bir baskıyla sınırlı kalıp hiç değişmemiştir', 'Yalnızca ölümünden sonra basılmıştır', 'Her baskıda kısaltılarak küçülmüştür'], 'Whitman, kitabı 1855\'ten ölümüne dek yeniden düzenledi ve genişletti; bu sürekli gelişen yapı \'ömür boyu yazılan kitap\' olarak anılır.'),
  ('Arthur Miller\'ın \'Bir Satıcının Ölümü\' oyununda Willy Loman\'ın Biff ile ilişkisindeki gerilimin nedeni nedir?', 'Willy\'nin oğluna yüklediği beklenti ile gerçeklik arasındaki uçurum', ['Biff\'in zengin olup babasından uzaklaşması ve onu küçümseyip aşağılaması', 'Willy\'nin savaşa gitmesi', 'Biff\'in evlenmeyi reddetmesi'], 'Willy, Amerikan Rüyası\'na körü körüne inanır; Biff gerçeği kabul edince baba-oğul çatışması patlak verir.'),
  ('Latin Amerika\'da Boom\'un en önemli özelliklerinden biri olarak edebiyat tarihçileri neyi gösterir?', 'Roman biçiminde deneysel yeniliklerin ve dünya çapında okur ilgisinin birlikte yaşanması', ['Yalnızca şiirin yükselmesi', 'Latin Amerika dillerinin yok olması', 'Sansürün tamamen kalkması'], '1960\'larda Cortázar, Fuentes, García Márquez ve Vargas Llosa gibi yazarlar yenilikçi romanlarla dünya okurlarına ulaştı.'),
  ('Pablo Neruda\'nın siyasi tutumu için hangisi söylenebilir?', 'Şili Komünist Partisi üyesiydi ve senatörlük yaptı', ['Askerî diktatörlüğü destekleyip onun bakanlığını yaptı', 'Hiç siyasetle ilgilenmedi', 'Monarşiyi savundu'], 'Neruda 1945\'te senatör seçildi ve komünist partiye katıldı; 1948\'de baskılar yüzünden gizlenmek zorunda kaldı.'),
  ('Borges \'Kurgular\' kitabında kurmaca ile gerçek ilişkisini nasıl işler?', 'Kurguları gerçek gibi, gerçekleri kurgu gibi sunarak ikisinin sınırını bulandırır', ['Yalnızca belgesel yazarak', 'Yalnızca tarih anlatarak', 'Her öyküyü gerçek hayattan alarak'], 'Borges, var olmayan kitaplara ve yazarlara gönderme yapar; okur kurmaca ile gerçek arasındaki sınırı sorgular.'),
  ('Remarque\'ın \'Batı Cephesinde Yeni Bir Şey Yok\' romanında Paul Bäumer\'in ölüm anındaki durumu neyi vurgular?', 'Savaşın sıradanlığını ve tek askerin değersizliğini', ['Büyük bir zaferin kutlanışını ve barışın sevincini coşkuyla', 'Subayların kahramanlığını', 'Barışın başlamasını'], 'Paul\'ün ölümü günlük raporda \'cephede yeni bir şey yok\' diye geçer; bu, bireyin savaş makinesi içindeki değersizliğini gösterir.'),
  ('Brecht\'in epik tiyatrosunda sahnedeki yabancılaştırma tekniklerinden biri hangisidir?', 'Oyuncunun seyirciye doğrudan seslenmesi veya afiş ve başlıkların kullanılması', ['Seyircinin karanlıkta ağlatılması', 'Gerçek kan akıtılması', 'Oyuncuların hep aynı kostümü giymesi'], 'Brecht, seyircinin sahneyi gerçek sanmasını engellemek için şarkılar, tabelalar ve doğrudan hitap gibi araçlar kullandı.'),
  ('Kayıp kuşak edebiyatının ortak kaygısını hangisi en iyi ifade eder?', 'Savaş sonrası değer yitimi karşısında yön bulamama', ['Savaş zaferinden duyulan gurur ve vatan sevgisinin yüceltilmesi', 'Dinî coşku', 'Sanayi başarısı'], 'Birinci Dünya Savaşı\'ndan sonra Hemingway ve Fitzgerald gibi yazarlar, eski değerlerin çöktüğü bir dünyada boşluk duygusunu anlattı.'),
  ('Bir şiir meraklısı Whitman\'ı ve Neruda\'yı karşılaştırırken hangi ortak özelliği vurgulayabilir?', 'İkisinin de halk ve doğa üzerine geniş soluklu şiirler yazması', ['İkisinin de yalnızca sone yazması', 'İkisinin de dinî ilahi yazması', 'İkisinin de hiç siyasete girmemesi'], 'Whitman ve Neruda serbest ve kapsayıcı bir üslupla halkı ve doğayı şiirlerinin merkezine aldı.'),
  ('Kerouac\'ın \'Yolda\' romanının el yazmasının hazırlanışıyla ilgili bilinen olgu nedir?', 'Yaklaşık üç hafta içinde sürekli bir kâğıt rulosuna yazılmıştır', ['Beş yıl boyunca her gün birkaç satır halinde yazılmıştır', 'Kerouac\'ın hapishanede dikte ettirdiği metinden derlenmiştir', 'Yayınevinin hazırladığı bir taslaktan yeniden kaleme alınmıştır'], 'Kerouac, 1951\'de romanı uzun bir kâğıt rulosuna aralıksız yazdı; bu çalışma biçimi kendiliğinden düzyazı anlayışının simgesidir.'),
  ('John Cheever\'ın \'Yüzücü\' öyküsünde Neddy Merrill\'in kendine koyduğu hedef nedir?', 'Komşularının havuzlarında yüzerek evine ulaşmak', ['Nehri yüzerek geçip karşı kıyıya varmak', 'Yaz sonunda şehir havuzu yarışına katılmak', 'Bir okyanus gemisinde yüzme eğitmeni olmak'], 'Neddy havuzdan havuza ilerledikçe mevsim, zaman ve hayat bozulur; öykü orta sınıf yaşamın sahte parlaklığının çözülüşünü anlatır.'),
  ('Rubén Darío\'nun 1888 tarihli \'Mavi...\' kitabı hangi nedenle önemlidir?', 'Latin Amerika Modernismosunun başlangıcı sayılması', ['Köleliğin kaldırılmasını savunan ilk kitap olması', 'Meksika Devrimi\'nin ilk destanı olması', 'Yerlici romanın ilk örneği olması'], 'Darío, bu kitapla Fransız Parnasizm ve Sembolizminin etkilerini İspanyolcaya taşıyarak yeni bir şiir dili açtı.'),
  ('Heine\'nin 1827 tarihli \'Şarkılar Kitabı\' (Buch der Lieder) hangi nedenle ün kazanmıştır?', 'Romantik aşk şiirlerini ironik bir kırılmayla sunması ve çokça bestelenmesi', ['Savaş marşlarını derlemesi', 'Orta Çağ efsanelerinin düzyazı çevirisi olması', 'Bilimsel şiirin ilk örneği olması'], 'Kitaptaki şiirler Schumann ve Schubert gibi bestecilerce müziğe uyarlandı; Heine\'yi geniş okur kitlesiyle buluşturdu.'),
  ('Goethe\'nin \'Faust\' ikinci bölümü ne zaman yayımlanmıştır?', 'Goethe\'nin ölümünün hemen ardından, 1832\'de', ['Birinci bölümle aynı yıl, 1808\'de', 'Goethe\'nin ölümünden elli yıl sonra', 'Goethe\'nin İtalya yolculuğu öncesinde'], 'Goethe ikinci bölümü yıllarca yazıp ölümünden kısa süre önce tamamladı; kitap 1832\'de yayımlandı.'),
  ('Gerçekçi Alman novellalarında sık kullanılan \'çerçeve hikâye\' tekniği nasıl işler?', 'Asıl öykü bir anlatıcının dinlediği ya da okuduğu bir hikâye olarak sunulur', ['Öykü yalnızca diyaloglardan oluşur', 'Öykü sondan başa doğru anlatılır', 'Öykü yazar tarafından hiç anlatılmaz'], 'Storm\'un Atlı Hayalet\'inde olduğu gibi, çerçeve anlatı asıl olayı bir aktarım katmanıyla verir ve okurda mesafe yaratır.'),
  ('Hemingway\'in \'Bir Gün Beklemek\' gibi kısa öykülerinde diyalog nasıl kullanılır?', 'Kısa ve yüzeysel görünen konuşmalarla asıl duyguyu dolaylı yoldan vermek için', ['Karakterlerin iç dünyasını uzun uzun açıklamak için', 'Okura felsefi açıklamalar yapmak için', 'Olay örgüsünü yazar yorumuyla bitirmek için'], 'Hemingway diyalogları yalın tutar; duygular konuşulmayanlarda saklıdır. Bu, buzdağı ilkesinin temel uygulamasıdır.'),
  ('Dickinson\'ın dizelerindeki tirelerin işlevi hakkında yaygın görüş hangisidir?', 'Duraklamalar, ritim ve anlam açıklığı yaratmak', ['Cümlenin bittiğini kesin olarak göstermek', 'Yazım hatalarını gizlemek', 'Sayfa kenarlarını doldurmak'], 'Dickinson\'ın tireleri nefes payı ve belirsizlik yaratır; okuru birden çok anlam arasında bırakır.'),
  ('Cortázar\'ın \'Seksek\' romanındaki \'okuma tablosu\' bölümlerinin sıralı okunmasıyla ilgili hangisi doğrudur?', 'Okur ya doğrusal sırada ya da tabloda belirtilen sırayla okuyabilir ve iki okuma farklı bir metin üretir', ['Okur yalnızca tablodaki sırayı kullanmak zorundadır', 'Sıralı okuma yasaktır', 'Tablo, kitabın sonundaki sözlüğe dayanır'], 'Yazar iki okuma biçimi önerir: baştan sona ve \'okuma tablosuna\' göre; ikincisi ek bölümleri araya sokarak romanı yeniden yapılandırır.'),
  ('Bir lise edebiyat kulübü \'dönemin siyasi baskısına karşı yazan\' iki Alman yazarı tanıtacak. Hangi ikili en uygundur?', 'Heine ve Brecht', ['Eichendorff ve Novalis', 'Fontane ve Storm', 'Hölderlin ve Rilke'], 'Heine sürgünde Prusya düzenini, Brecht de Nazi rejimini hiciv ve eleştiriyle yazdı; diğer ikililer daha çok doğa, lirik ya da gerçekçi anlatıyla öne çıkar.'),
  ('Bir öğrenci, Amerikan edebiyatında \'Güney\' kültürünü ve ırk meselesini işleyen yazarları listeliyor. Hangi liste uygundur?', 'Faulkner, Harper Lee, Zora Neale Hurston', ['Whitman, Thoreau, Emerson', 'Poe, Hawthorne, Melville', 'Ginsberg, Kerouac, Burroughs'], 'Bu üç yazar Güney\'in toplumunu ve ırkçılığı farklı biçimlerde işler; diğer listeler Transandantalist, Karanlık Romantik ve Beat çevrelerini kapsar.'),
];
